    const slot = value + 128;
    lengths[slot] = text.length;
    for (let index = 0; index < text.length; index += 1) codes[slot * LOCAL_SEMANTIC_ROUTING_INT8_CODE_WIDTH + index] = text.charCodeAt(index);
