function settingDescription(name, key, fallback = "") {
  return fallback || SETTING_DESCRIPTIONS[key] || SETTING_DESCRIPTIONS[name] || "";
}

function sanitizeLogData(value) {
  if (value == null) return value;
  if (typeof value === "string") return redactSecrets(value);
  if (typeof value === "number" || typeof value === "boolean") return value;
  if (Array.isArray(value)) return value.map(sanitizeLogData);
  if (typeof value === "object") {
    const out = {};
    for (const [key, item] of Object.entries(value)) {
      if (/key|token|authorization|secret|password/i.test(key)) out[key] = "[redacted]";
      else out[key] = sanitizeLogData(item);
    }
    return out;
  }
  return String(value);
}

function redactSecrets(value) {
  return String(value || "")
    .replace(/sk-ant-[A-Za-z0-9_-]{20,}/g, "[redacted-anthropic-key]")
    .replace(/AIza[0-9A-Za-z_-]{20,}/g, "[redacted-google-key]")
    .replace(/sk-(?:proj-)?[0-9A-Za-z_-]{20,}/g, "[redacted-openai-key]")
    .replace(/Bearer\s+[0-9A-Za-z._-]+/gi, "Bearer [redacted]");
}

function randomSetupToken() {
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
  const bytes = new Uint8Array(32);
  if (globalThis.crypto?.getRandomValues) globalThis.crypto.getRandomValues(bytes);
  else for (let i = 0; i < bytes.length; i += 1) bytes[i] = Math.floor(Math.random() * 256);
  return Array.from(bytes, (byte) => alphabet[byte % alphabet.length]).join("");
}

function isHttpsUrl(value) {
  try {
    const url = new URL(String(value || ""));
    return url.protocol === "https:";
  } catch {
    return false;
  }
}

function normalizeHttpsUrl(value) {
  const text = String(value || "").trim();
  if (!text) return "";
  if (/^https?:\/\//i.test(text)) return text.replace(/^http:\/\//i, "https://");
  return `https://${text}`;
}

function textSetting(containerEl, name, desc, plugin, key) {
  new Setting(containerEl).setName(name).setDesc(settingDescription(name, key, desc)).addText((text) => text.setValue(String(plugin.settings[key] || "")).onChange(async (value) => {
    plugin.settings[key] = key === "workerUrl" ? normalizeHttpsUrl(value) : value;
    await plugin.saveSettings();
  }));
}

// System One decision model settings (optional). One toggle; when it is on,
// one Server address field, one Check connection button with a status line,
// and a collapsed Advanced subsection. The row model below is pure (no DOM,
// no network) so the local tests can assert the exact row set; rendering and
// toggling never make network calls by themselves — only the button does.
function systemOneCalibrationDetailsText(summary) {
  if (!summary || typeof summary !== "object" || !summary.verdict) {
    return "Calibration runs when you click Check connection. It checks that the System One decision model separates related from unrelated notes on this vault, using short excerpts of your own notes, and derives the display bands. It checks basic discrimination, not fine ranking quality.";
  }
  if (summary.verdict === "ok") {
    return `Last calibration: ok. Separation (AUC) ${Number(summary.auc).toFixed(2)}; central band from p >= ${Number(summary.cutoffHigh).toFixed(2)}, background band at p <= ${Number(summary.cutoffLow).toFixed(2)}. Calibration checks basic discrimination on your vault, not fine ranking quality.`;
  }
  if (summary.verdict === "weak") {
    const auc = Number.isFinite(Number(summary.auc)) ? Number(summary.auc).toFixed(2) : "n/a";
    return `Last calibration: weak separation (AUC ${auc}). The System One decision model may still order rows, but no relevance bands are shown to the model. Calibration checks basic discrimination on your vault, not fine ranking quality.`;
  }
  if (summary.verdict === "untested") {
    return "Last calibration: no usable vault samples were found, so the System One decision model only orders rows and no relevance bands are shown. Calibration checks basic discrimination on your vault, not fine ranking quality.";
  }
  return "Last check failed; the System One decision model is not used for bands. Calibration checks basic discrimination on your vault, not fine ranking quality.";
}

function systemOneStatusLineText(summary, stale = false) {
  if (!summary || typeof summary !== "object" || !summary.verdict) return "Not checked yet.";
  let line = "";
  if (summary.verdict === "failed") {
    line = summary.reason === "unreachable" ? "Can't reach the server" : "Server answered but not in System One format";
  } else {
    const model = String(summary.model || "System One decision model");
    const latency = Number.isFinite(Number(summary.latencyMs)) ? Number(summary.latencyMs) : 0;
    if (summary.verdict === "ok") line = `Connected: ${model} - ${latency} ms - calibration OK`;
    else if (summary.verdict === "weak") line = `Connected: ${model} - ${latency} ms - Calibration found weak separation: using the normal order`;
    else line = `Connected: ${model} - ${latency} ms - calibration untested: using the normal order`;
  }
  return stale ? `${line} - Recalibrate` : line;
}

// Calibration transparency (user ruling): one plain sentence shown before the
// run, the exact stale notice, and the plain-language result view for the
// settings panel. All pure (no DOM, no network) so the local tests can assert
// the exact strings.
const SYSTEM_ONE_STALE_NOTICE = "Calibration is out of date for this model/index. Click Check connection to recalibrate.";

// Synchronous estimate of the number of calibration checks (scoring calls)
// the vault/index will produce: one check per sampled marked-action note
// (heading fallback), capped by the calibration positive limit. No network,
// no vault reads; feeds the "about N checks" up-front sentence.
function systemOnePlannedCheckCount(plugin) {
  try {
    const settings = plugin?.settings || DEFAULT_SETTINGS;
    const chunks = Array.isArray(plugin?.semanticIndex) ? plugin.semanticIndex : [];
    const usable = chunks.filter((chunk) => chunk
      && typeof chunk.text === "string" && chunk.text.trim()
      && !chunk.metadataOnly
      && chunk.evidenceEligibility !== "metadata"
      && isEmbeddingVector(chunk.embedding) && chunk.embedding.length);
    const limit = Math.max(1, Number(EVIDENCE_RERANK_CALIBRATION_POSITIVE_LIMIT) || 12);
    const markerRegex = noteActionMarkerRegex(settings);
    const markerPaths = uniqueValues(usable.filter((chunk) => markerRegex.test(chunk.text)).map((chunk) => String(chunk.path || ""))).filter(Boolean);
    if (markerPaths.length) return Math.min(markerPaths.length, limit);
    const headings = usable.filter((chunk) => /^#{1,6}\s+\S/.test(String(chunk.text || "").trim()));
    return Math.min(headings.length, limit);
  } catch {
    return 0;
  }
}

// The up-front sentence: what is sent, about how many checks, and that the
// plugin stores nothing on the server.
function systemOneTransparencySentence(plugin) {
  const checks = systemOnePlannedCheckCount(plugin);
  const countText = checks > 0
    ? `about ${checks} check${checks === 1 ? "" : "s"}`
    : `up to ${Math.max(1, Number(EVIDENCE_RERANK_CALIBRATION_POSITIVE_LIMIT) || 12)} checks`;
  return `Check connection sends short excerpts from a sample of your own notes to your server (${countText}); the plugin stores nothing on the server.`;
}

// Plain-language result view for the settings panel: verdict, what it means
// (relevance labels will / will not be shown to the writing model; order
// only), the three numbers for the expandable Details row, and when it ran.
function systemOneResultViewModel(summary) {
  if (!summary || typeof summary !== "object" || !summary.verdict) {
    return { verdictText: "", meaningText: "", detailsText: "", whenText: "" };
  }
  const model = String(summary.model || "System One decision model");
  const latency = Number.isFinite(Number(summary.latencyMs)) ? Number(summary.latencyMs) : 0;
  const fmt = (value) => (value === null || value === undefined || !Number.isFinite(Number(value)) ? "n/a" : Number(value).toFixed(2));
  let verdictText = "";
  let meaningText = "";
  if (summary.verdict === "ok") {
    verdictText = "Last calibration: ok.";
    meaningText = "Relevance labels will be shown to the writing model. The System One decision model only changes the order of your evidence rows.";
  } else if (summary.verdict === "weak") {
    verdictText = `Last calibration: weak separation (AUC ${fmt(summary.auc)}).`;
    meaningText = "Relevance labels will not be shown to the writing model. The System One decision model only changes the order of your evidence rows.";
  } else if (summary.verdict === "untested") {
    verdictText = "Last calibration: untested - no usable samples from your notes were found.";
    meaningText = "Relevance labels will not be shown to the writing model. The System One decision model only orders your evidence rows.";
  } else {
    verdictText = "Last check failed.";
    meaningText = "Relevance labels will not be shown to the writing model.";
  }
  const detailsText = `Model: ${model}; latency ${latency} ms. Separation (AUC) ${fmt(summary.auc)}; central band cutoff ${fmt(summary.cutoffHigh)}; background band cutoff ${fmt(summary.cutoffLow)}.`;
  const whenText = summary.checkedAt ? `Checked: ${String(summary.checkedAt)}` : "";
  return { verdictText, meaningText, detailsText, whenText };
}

// Row model for the System One decision model section: the renderer below and
// the local tests consume the same structure. Off => only the toggle row.
function systemOneDecisionModelSettingsModel(plugin) {
  const enabled = plugin?.settings?.evidenceRerankEnabled === true;
  const summary = plugin?.settings?.evidenceRerankCalibration && typeof plugin.settings.evidenceRerankCalibration === "object"
    ? plugin.settings.evidenceRerankCalibration
    : null;
  const stale = typeof plugin?.systemOneCalibrationStale === "function" ? plugin.systemOneCalibrationStale() === true : false;
  return {
    enabled,
    toggle: { type: "toggle", name: "System One decision model (optional)", key: "evidenceRerankEnabled" },
    rows: enabled ? [
      { type: "url", name: "Server address", key: "evidenceRerankUrl" },
      { type: "check", name: "Check connection" },
      { type: "status", text: systemOneStatusLineText(summary, stale) }
    ] : [],
    advanced: enabled ? [
      { type: "secret", name: "API key (optional)", key: "evidenceRerankApiKey" },
      { type: "number", name: "Maximum rows scored per task", key: "evidenceRerankMaxCandidates" },
      { type: "number", name: "Per-task timeout (ms)", key: "evidenceRerankTimeoutMs" },
      { type: "toggle", name: "Show relevance bands to the model", key: "evidenceRerankShowBands" },
      { type: "toggle", name: "Max efficiency", key: "evidenceRerankTier" },
      { type: "note", text: systemOneCalibrationDetailsText(summary) }
    ] : []
  };
}

// Server address input: accepts only an explicit http(s) URL and saves the
// normalized origin+path (no trailing slash). Invalid input keeps the
// previously saved value. Saving never makes a network call.
function systemOneServerAddressSetting(containerEl, plugin) {
  new Setting(containerEl)
    .setName("Server address")
    .setDesc(settingDescription("Server address", "evidenceRerankUrl"))
    .addText((text) => text.setValue(String(plugin.settings.evidenceRerankUrl || "")).onChange(async (value) => {
      const trimmed = String(value || "").trim();
      if (!trimmed) {
        plugin.settings.evidenceRerankUrl = "";
        await plugin.saveSettings();
        return;
      }
      let normalized = "";
      try {
        const parsed = new URL(trimmed);
        if (parsed.protocol === "http:" || parsed.protocol === "https:") {
          normalized = `${parsed.origin}${parsed.pathname.replace(/\/+$/, "")}`;
        }
      } catch { normalized = ""; }
      if (!normalized) return;
      plugin.settings.evidenceRerankUrl = normalized;
      await plugin.saveSettings();
    }));
}

function systemOneDecisionModelSettings(containerEl, plugin) {
  new Setting(containerEl)
    .setName("System One decision model (optional)")
    .setDesc(settingDescription("System One decision model (optional)", "evidenceRerankEnabled"))
    .addToggle((toggle) => toggle.setValue(plugin.settings.evidenceRerankEnabled === true).onChange(async (value) => {
      plugin.settings.evidenceRerankEnabled = value === true;
      await plugin.saveSettings();
      renderSystemOneDecisionModelBody();
    }));
  const body = containerEl.createDiv({ cls: "semantic-todoist-systemone-body" });
  let statusEl = null;
  let running = false;
  let controller = null;
  async function runCheck(button) {
    if (running) {
      controller?.abort?.();
      return;
    }
    running = true;
    controller = new AbortController();
    button.setButtonText("Cancel");
    statusEl.setText("Checking connection...");
    // A Notice only when the settings panel is closed: the panel text is
    // primary and the status line mirrors progress, so a Notice is added only
    // when neither is visible, and never more than one per run boundary.
    const panelClosedAtStart = Boolean(statusEl && statusEl.isConnected === false);
    if (panelClosedAtStart) { try { new Notice("Checking the System One decision model on your notes..."); } catch {} }
    let result = null;
    try {
      result = await plugin.systemOneCheckConnection({ signal: controller.signal, onStatus: (text) => statusEl.setText(text) });
    } catch { result = null; }
    running = false;
    controller = null;
    button.setButtonText("Check connection");
    statusEl.setText(result?.status || "Can't reach the server");
    if (statusEl && statusEl.isConnected === false && result?.status) { try { new Notice(result.status); } catch {} }
    // Re-render only when a summary exists: the plain-language verdict, the
    // Details row, when it ran and the Recalibrate button stay visible. A
    // cancelled run keeps its "Check cancelled" text in place.
    if (result?.summary) renderSystemOneDecisionModelBody();
  }
  function renderSystemOneDecisionModelBody() {
    body.empty();
    statusEl = null;
    const model = systemOneDecisionModelSettingsModel(plugin);
    if (!model.enabled) {
      body.style.display = "none";
      return;
    }
    body.style.display = "";
    systemOneServerAddressSetting(body, plugin);
    // Transparency before anything runs: one plain sentence (what is sent,
    // about how many checks, nothing stored on the server). Never a network
    // call; rendering alone starts nothing.
    body.createDiv({ cls: "semantic-todoist-systemone-transparency", text: systemOneTransparencySentence(plugin) });
    const summary = plugin.settings.evidenceRerankCalibration && typeof plugin.settings.evidenceRerankCalibration === "object" ? plugin.settings.evidenceRerankCalibration : null;
    const stale = typeof plugin.systemOneCalibrationStale === "function" ? plugin.systemOneCalibrationStale() === true : false;
    // Never silent: a changed model identity / index generation shows the
    // exact notice and never auto-runs a request.
    if (stale) body.createDiv({ cls: "semantic-todoist-systemone-stale", text: SYSTEM_ONE_STALE_NOTICE });
    const check = new Setting(body).setName("Check connection").setDesc("Connects to the server above, verifies the System One decision format, then calibrates on this vault. Sends short excerpts of your notes to the server you configured.");
    statusEl = check.settingEl.createDiv({ cls: "semantic-todoist-systemone-status", text: model.rows.find((row) => row.type === "status")?.text || "Not checked yet." });
    check.addButton((button) => button.setButtonText("Check connection").onClick(async () => { await runCheck(button); }));
    if (summary) {
      const view = systemOneResultViewModel(summary);
      body.createDiv({ cls: "semantic-todoist-systemone-verdict", text: view.verdictText });
      body.createDiv({ cls: "semantic-todoist-systemone-meaning", text: view.meaningText });
      if (view.whenText) body.createDiv({ cls: "semantic-todoist-systemone-when", text: view.whenText });
      const details = settingsDisclosure(body, "Details", view.detailsText);
      details.createDiv({ cls: "semantic-todoist-systemone-details", text: view.detailsText });
      new Setting(body).setName("Recalibrate").setDesc("Runs Check connection again to recalibrate the System One decision model on this vault.").addButton((button) => button.setButtonText("Recalibrate").onClick(async () => { await runCheck(button); }));
    }
    const advanced = settingsDisclosure(body, "Advanced", "API key, row budget, timeout, relevance bands and calibration details.");
    secretSetting(advanced, "API key (optional)", plugin, "evidenceRerankApiKey");
    numberSetting(advanced, "Maximum rows scored per task", plugin, "evidenceRerankMaxCandidates");
    numberSetting(advanced, "Per-task timeout (ms)", plugin, "evidenceRerankTimeoutMs");
    toggleSetting(advanced, "Show relevance bands to the model", "Show a coarse relevance band (central or background) on evidence rows to the model after a successful calibration. The raw probability is never shown.", plugin, "evidenceRerankShowBands");
    toggleSetting(advanced, "Max efficiency", "Send fewer notes in full: the System One decision model picks the 8 most relevant passages to send in full and a one-line pointer for the next 16, so each request is shorter and cheaper. Needs the System One decision model to be on. Off by default.", plugin, "evidenceRerankTier");
    advanced.createDiv({ cls: "semantic-todoist-systemone-calibration", text: model.advanced.find((row) => row.type === "note")?.text || "" });
  }
  renderSystemOneDecisionModelBody();
}

const STABLE_PROVIDER_LABELS = Object.freeze({
  openai: "OpenAI",
  gemini: "Google Gemini",
  openrouter: "OpenRouter",
  anthropic: "Anthropic",
  openwebui: "Self-Hosted OpenWebUI",
  customopenai: "Custom OpenAI-compatible"
});

const STABLE_OPERATION_LABELS = Object.freeze({
  "chat-query": "Chat queries",
  "prompt-response": "Saved prompts",
  "task-generation": "Task generation",
  "task-description": "Task descriptions",
  "section-title": "Section titles",
  scheduler: "Scheduler estimates",
  policy: "Policy updates",
  deduplication: "Duplicate review"
});

function providerAdapterError(provider, code, message, status = 0, retryable = false) {
  const statusText = Number(status || 0) > 0 ? ` ${Number(status)}` : "";
  const error = new Error(`${String(provider || "provider")} request failed${statusText}: ${redactProviderAdapterDetail(message || code || "provider-error")}`);
  error.provider = stableSupportedProvider(provider, "openrouter");
  error.providerError = {
    provider: error.provider,
    code: String(code || "provider-error").slice(0, 80),
    status: Number(status || 0),
    retryable: Boolean(retryable)
  };
  error.code = error.providerError.code;
  error.status = error.providerError.status;
  return error;
}

function isRetryableProviderStatus(status) {
  // 529 is Anthropic's overloaded_error (server overload). No other supported
  // provider emits it, so the retry classification of every other status is
  // unchanged; adding it here keeps the same-provider fallback working for
  // Anthropic the way 429/5xx already do elsewhere.
  return [408, 409, 425, 429, 500, 502, 503, 504, 529].includes(Number(status));
}

function redactProviderAdapterDetail(value) {
  return redactSecrets(value)
    .replace(/https?:\/\/[^\s"'<>]+/gi, "[redacted-endpoint]")
    .replace(/\b(?:sk-or-v1|sk-ant)-[0-9A-Za-z_-]+/gi, "[redacted-provider-key]")
    .replace(/\b(api[_-]?key|token|password|secret|authorization)\s*[:=]\s*["']?[^\s,"'}]+/gi, "$1=[redacted]");
}

// Slice C: classify a provider error as "this endpoint rejected the reasoning
// effort field". Only explicit parameter rejections count: HTTP 400/422 (and
// 404/501, which gateways also use for unknown request parameters) whose error
// text names reasoning_effort/reasoning together with an unsupported, unknown
// or invalid qualifier. Generic 400s (schema, context length), auth errors and
// server/rate-limit errors never classify, so their surfaces stay unchanged.
const REASONING_REJECTION_STATUSES = [400, 404, 422, 501];

function isReasoningEffortRejection(error) {
  if (!error || typeof error !== "object") return false;
  const providerError = error.providerError && typeof error.providerError === "object" ? error.providerError : {};
  const status = Number(providerError.status ?? error.status ?? 0);
  if (!REASONING_REJECTION_STATUSES.includes(status)) return false;
  const detailText = [error.message, error.detail, providerError.detail, providerError.message]
    .filter((part) => part !== undefined && part !== null && part !== "")
    .map((part) => String(part))
    .join(" ")
    .toLowerCase();
  const codeText = [error.code, providerError.code]
    .filter((part) => part !== undefined && part !== null && part !== "")
    .map((part) => String(part))
    .join(" ")
    .toLowerCase();
  const namingText = `${detailText} ${codeText}`;
  // Anthropic native Messages API names its reasoning fields `output_config.effort`
  // and `thinking.type`; recognise those field names alongside the OpenAI-style
  // reasoning/reasoning_effort vocabulary. The schema keyword rejection
  // (`output_config.format.schema`) deliberately does not match.
  const namesParameter = /reasoning[_\-.\s]?effort/.test(namingText)
    || /(?:^|[^a-z0-9_])reasoning(?:$|[^a-z0-9_])/.test(namingText)
    || /output[_\-.\s]?config[_\-.\s]?effort/.test(namingText)
    || /thinking[_\-.\s]?type/.test(namingText)
    || (/input\s+should\s+be/i.test(detailText) && /low|medium|high|xhigh|max/i.test(detailText));
  if (!namesParameter) return false;
  // Qualifier words must come from the provider's own detail text; a generic
  // "invalid_request_error" code alone must never qualify a 400.
  if (/unsupported|not\s+supported|unknown|unrecognized|unexpected|invalid|drop_params|extra[_\-.\s]?(?:inputs|fields|keys)|forbidden/.test(detailText)) return true;
  // Anthropic native Messages API rejects unsupported effort values with a specific message shape.
  if (/input\s+should\s+be/i.test(detailText) && /low|medium|high|xhigh|max/i.test(detailText)) return true;
  return /unsupported|unknown|unrecognized|drop_params|unexpected|forbidden/.test(codeText);
}

// --- Opt-in external debug logging (P1) -------------------------------------
// Explicitly started, opt-in, bounded and sanitized frames emitted to an
// external collector that attached over the loopback debugging channel. No
// renderer filesystem work, no aggregation maps and no response parsing: frames
// are strings containing flat JSON objects. Nothing here runs unless a session
// is active and a capture context is threaded to the transport boundary.
const PROVIDER_CAPTURE_MAX_BYTES = 64 * 1024 * 1024;
const PROVIDER_CAPTURE_MARKER_RESERVE = 1024;
const PROVIDER_CAPTURE_SECRET_MIN_LENGTH = 6;
// Frozen bounds: at most 1 MiB of source text per payload, 4096 UTF-16 code
// units per sanitized text part, 64 KiB UTF-8 per encoded frame and 64 MiB per
// session including terminal markers. Over-limit diagnostics are omitted or
// incomplete, never silently truncated.
const PROVIDER_CAPTURE_SOURCE_LIMIT_BYTES = 1024 * 1024;
const PROVIDER_CAPTURE_TEXT_PART_LIMIT = 4096;
const PROVIDER_CAPTURE_FRAME_LIMIT_BYTES = 64 * 1024;
const PROVIDER_CAPTURE_ACK_WINDOW_MS = 5000;

function providerCaptureId(prefix = "req") {
  const random = Math.random().toString(16).slice(2, 12);
  const time = Date.now().toString(16);
  return `${prefix}-${time}-${random}`;
}

function providerCaptureByteLength(value) {
  const text = typeof value === "string" ? value : (value === undefined || value === null ? "" : String(value));
  if (typeof Buffer !== "undefined" && typeof Buffer.byteLength === "function") {
    try {
      return Buffer.byteLength(text, "utf8");
    } catch (error) {
      return text.length;
    }
  }
  return text.length;
}

// Ephemeral known credential literals derived from the exact configured provider
// credentials. Kept in memory only: never persisted, never logged, never written
// to the capture file.
function providerCaptureCredentialValues(settings = {}) {
  const source = settings && typeof settings === "object" ? settings : {};
  const candidates = [
    source.openaiApiKey,
    source.openrouterApiKey,
    source.googleApiKey,
    source.customOpenAIApiKey,
    source.openwebuiApiKey,
    source.openwebuiJwt,
    source.openwebuiSessionToken,
    source.workerToken
  ];
  const values = [];
  for (const candidate of candidates) {
    const text = typeof candidate === "string" ? candidate.trim() : "";
    if (text.length >= PROVIDER_CAPTURE_SECRET_MIN_LENGTH) values.push(text);
  }
  return Array.from(new Set(values));
}

// Per-request credential values read from the request headers only to redact the
// captured body. The header values themselves are never captured or persisted.
function providerCaptureRequestCredentialValues(request = {}) {
  const headers = request && typeof request === "object" ? request.headers : null;
  if (!headers || typeof headers !== "object") return [];
  const values = [];
  for (const [name, raw] of Object.entries(headers)) {
    if (!/(authorization|api[-_]?key|x-goog-api-key|cookie|token|jwt)/i.test(String(name || ""))) continue;
    const value = String(typeof raw === "string" ? raw : "").replace(/^Bearer\s+/i, "").trim();
    if (value.length >= PROVIDER_CAPTURE_SECRET_MIN_LENGTH) values.push(value);
  }
  return values;
}

// Structural + literal redaction used only for capture. Throws on unexpected
// failure so the caller omits the payload rather than persisting raw text. Native
// usage fields (prompt_tokens/completion_tokens/total_tokens/cost/...) are not
// credential-shaped and are preserved.
function providerCaptureSanitizeText(value, knownSecrets = []) {
  let text = typeof value === "string" ? value : (value === undefined || value === null ? "" : String(value));
  if (!text) return text;
  const secrets = Array.from(new Set((knownSecrets || [])
    .filter((secret) => typeof secret === "string" && secret.length >= PROVIDER_CAPTURE_SECRET_MIN_LENGTH)))
    .sort((left, right) => right.length - left.length);
  for (const secret of secrets) {
    if (!secret) continue;
    text = text.split(secret).join("[redacted-credential]");
  }
  text = text.replace(/("(?:api[_-]?key|api-key|password|passwd|secret|client[_-]?secret|access[_-]?token|refresh[_-]?token|id[_-]?token|token|authorization|x-goog-api-key|cookie)"\s*:\s*)(?:"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|[^,}\s]+)/gi, '$1"[redacted]"');
  text = text.replace(/\beyJ[A-Za-z0-9_-]{4,}\.[A-Za-z0-9_-]{4,}\.[A-Za-z0-9_-]{4,}\b/g, "[redacted-jwt]");
  text = text.replace(/\bBearer\s+[0-9A-Za-z._~+/=-]+/gi, "Bearer [redacted]");
  text = text.replace(/\b(?:sk-or-v1|sk-ant|sk-proj|sk)-[0-9A-Za-z_-]{10,}/gi, "[redacted-provider-key]");
  text = text.replace(/\bAIza[0-9A-Za-z_-]{20,}\b/g, "[redacted-google-key]");
  text = text.replace(/\b(api[_-]?key|password|passwd|secret|client[_-]?secret|access[_-]?token|refresh[_-]?token|authorization)\b\s*[:=]\s*["']?[^\s,"'}]+/gi, "$1=[redacted]");
  return text;
}

function providerCaptureSafeText(value, knownSecrets) {
  try {
    return { ok: true, text: providerCaptureSanitizeText(value, knownSecrets) };
  } catch (error) {
    return { ok: false, text: null };
  }
}

function providerCaptureSameVaultPath(left, right) {
  const normalize = (value) => String(value || "").replace(/\\/g, "/").replace(/\/+$/, "").toLowerCase();
  const normalizedLeft = normalize(left);
  return normalizedLeft !== "" && normalizedLeft === normalize(right);
}

// Controlled error codes for wrapper failure events: an existing bounded code
// is preserved, anything else collapses to the fixed fallback.
function debugLogErrorCode(error, fallback) {
  const code = error && typeof error.code === "string" ? error.code : "";
  return /^[a-z0-9][a-z0-9-]{0,79}$/i.test(code) ? code : fallback;
}

// Bounded wire-text handoff: the source text is admitted (1 MiB ceiling) before
// sanitization, the COMPLETE text is sanitized before framing, and the
// sanitized result is sliced into at most 4096 UTF-16 units per 1-based part.
// JSON escaping preserves reconstruction even at surrogate boundaries. Missing
// or failed text becomes an explicit omission with a controlled reason; raw
// text never appears in an omission event.
function providerCaptureEmitWireText(sink, base, field, rawText, knownSecrets) {
  const omit = (reason, observedSize) => {
    safeProviderCapture(sink, Object.assign({}, base, {
      event: "payload-omitted",
      at: deviceTimestamp(),
      field,
      reason,
      observedSize
    }));
  };
  if (rawText === undefined || rawText === null) {
    // A response without wire text is an explicit omission; an absent request
    // body (GET/poll) simply has no payload to record.
    if (field === "response") omit("wire-text-unavailable", null);
    return;
  }
  if (typeof rawText !== "string") {
    omit("wire-text-not-string", null);
    return;
  }
  const observedSize = providerCaptureByteLength(rawText);
  if (observedSize > PROVIDER_CAPTURE_SOURCE_LIMIT_BYTES) {
    if (typeof sink.notePayloadFailure === "function") sink.notePayloadFailure("oversize");
    omit("source-text-over-limit", observedSize);
    return;
  }
  const sanitized = providerCaptureSafeText(rawText, knownSecrets);
  if (!sanitized.ok) {
    if (typeof sink.notePayloadFailure === "function") sink.notePayloadFailure("redaction");
    omit("redaction-failed", observedSize);
    return;
  }
  const text = sanitized.text;
  const parts = Math.max(1, Math.ceil(text.length / PROVIDER_CAPTURE_TEXT_PART_LIMIT));
  for (let part = 0; part < parts; part += 1) {
    safeProviderCapture(sink, Object.assign({}, base, {
      event: "text-part",
      at: deviceTimestamp(),
      field,
      // 1-based part index: part 1 of `parts` (frozen contract).
      part: part + 1,
      parts,
      text: text.slice(part * PROVIDER_CAPTURE_TEXT_PART_LIMIT, (part + 1) * PROVIDER_CAPTURE_TEXT_PART_LIMIT)
    }));
  }
}

// Central bounded/sanitized handoff for plugin-generated debug events (the
// guarded debugLog entry and usage observations). Every string field is
// admitted (1 MiB) BEFORE sanitization and sanitized with the session's
// ephemeral known secrets; a bound or redaction failure omits the whole event
// with a controlled reason and marks the session incomplete through the
// existing terminal flow. Non-string primitives pass through; nested or
// unreadable values are rejected without traversal.
function providerCaptureSanitizeDebugData(session, data) {
  const markIncomplete = (reason) => {
    if (session && typeof session.markIncomplete === "function") session.markIncomplete(reason);
  };
  let entries;
  try {
    entries = Object.entries(data && typeof data === "object" ? data : {});
  } catch (error) {
    markIncomplete("payload-invalid");
    return null;
  }
  const knownSecrets = Array.isArray(session && session.knownSecrets) ? session.knownSecrets : [];
  const out = {};
  for (const [key, value] of entries) {
    if (value === null || typeof value === "number" || typeof value === "boolean") {
      out[key] = value;
      continue;
    }
    if (typeof value !== "string") {
      markIncomplete("payload-invalid");
      return null;
    }
    const observedSize = providerCaptureByteLength(value);
    if (observedSize > PROVIDER_CAPTURE_SOURCE_LIMIT_BYTES) {
      if (session && typeof session.notePayloadFailure === "function") session.notePayloadFailure("oversize");
      markIncomplete("payload-over-limit");
      return null;
    }
    const safe = providerCaptureSafeText(value, knownSecrets);
    if (!safe.ok) {
      if (session && typeof session.notePayloadFailure === "function") session.notePayloadFailure("redaction");
      markIncomplete("redaction-failed");
      return null;
    }
    out[key] = safe.text;
  }
  return out;
}

function providerCaptureExcludedRequest(request, captureContext = null) {
  if (captureContext && captureContext.role === "authentication") return true;
  if (captureContext && captureContext.role === "discovery") return true;
  const url = String(request?.url || "");
  if (/\/auths\/signin\b/i.test(url)) return true;
  // Model/tag DISCOVERY only, matched on the path with any query/hash stripped:
  //   list   `GǪ/models` or `GǪ/models/` (OpenAI, OpenAI-compatible, Gemini)
  //   detail `GǪ/models/<id>` (no action suffix)
  // Gemini INFERENCE shares the `/models/` path segment but appends a `:method`
  // action suffix (`:generateContent` / `:embedContent`). Those are billable
  // inference requests and must be captured, so the detail branch refuses any
  // path whose final segment contains a `:` action separator.
  const pathOnly = url.split(/[?#]/)[0];
  if (/\/(?:models|tags)\/?$/i.test(pathOnly)) return true;
  if (/\/(?:models|tags)\/[^/:#]*$/i.test(pathOnly)) return true;
  return false;
}

// One transient opt-in debug-log session bound to an attached external
// collector. It owns sequence/byte accounting, bounded admission and the
// stop/drain acknowledgement window; it performs NO renderer filesystem work
// and keeps NO response-index or usage aggregation maps. Frames are strings
// containing flat JSON objects: {v:1, sessionId, seq, at, event, data}.
class DebugLogSession {
  constructor(options = {}) {
    // The collector's session id is adopted by the caller; a direct construction
    // without one is only reachable from the test seam.
    this.id = String(options.sessionId || providerCaptureId("session"));
    this.maxBytes = Number(options.maxBytes) > 0 ? Number(options.maxBytes) : PROVIDER_CAPTURE_MAX_BYTES;
    this.reserve = Math.min(PROVIDER_CAPTURE_MARKER_RESERVE, Math.max(64, Math.floor(this.maxBytes / 8)));
    this.bytesWritten = 0;
    this.entryCount = 0;
    this.omittedCount = 0;
    this.errorCount = 0;
    this.payloadOmittedCount = 0;
    this.payloadIncompleteCount = 0;
    this.redactionFailureCount = 0;
    this.serializationFailureCount = 0;
    this.incomplete = false;
    this.incompleteReason = "";
    this.available = typeof options.emitFrame === "function";
    this.unavailableReason = this.available ? "" : "debug-sink-unavailable";
    this.startedAt = deviceTimestamp();
    this._emit = this.available ? options.emitFrame : null;
    this._onFinalize = typeof options.onFinalize === "function" ? options.onFinalize : null;
    // Ephemeral known credential literals (in memory only; never persisted).
    this.knownSecrets = Array.isArray(options.knownSecrets)
      ? options.knownSecrets.filter((secret) => typeof secret === "string" && secret.length >= PROVIDER_CAPTURE_SECRET_MIN_LENGTH)
      : [];
    // Admission/lifecycle: stop blocks NEW admissions while in-flight admitted
    // requests keep draining to the same collector; a matching final
    // acknowledgement completes the session, a 5s timeout marks it incomplete.
    this.accepting = true;
    this.closeRequested = false;
    this.finalized = false;
    this.completed = false;
    this.finalDrainScheduled = false;
    this.finalSeq = null;
    this.acknowledgedSeq = 0;
    this._ackTimer = null;
    this.pending = 0;
    this.seq = 0;
    if (!this.available) {
      this._markIncomplete("debug-sink-unavailable");
    } else {
      // session-start is sequence 1; a sink that cannot accept it is marked
      // incomplete by the emitter and can never complete.
      this._emitTerminal("session-start", {});
    }
  }

  admitting() {
    return this.available && this.accepting && !this.finalized && !this.incomplete;
  }

  lifecycleState() {
    if (this.finalized) return this.completed ? "complete" : "incomplete";
    if (this.closeRequested) return "draining";
    return this.accepting ? "active" : "inactive";
  }

  beginRequest() {
    if (!this.admitting()) return false;
    this.pending += 1;
    return true;
  }

  endRequest() {
    this.pending = Math.max(0, this.pending - 1);
    if (this.closeRequested && this.pending === 0) this._scheduleFinalDrain();
  }

  notePayloadFailure(kind) {
    if (kind === "redaction") this.redactionFailureCount += 1;
    this.payloadOmittedCount += 1;
    this.payloadIncompleteCount += 1;
  }

  // Controlled incompleteness signal for central bound/sanitization failures;
  // never touches a finalized session and never throws into callers.
  markIncomplete(reason) {
    if (this.finalized) return;
    this._markIncomplete(reason);
  }

  // Transport/usage/wrapper handoff. Only flat primitives are accepted: any
  // nested or unreadable value marks the session incomplete with a controlled
  // reason and drops the whole event without serialization, so no diagnostic
  // graph traversal can reach the sink and no drop can look like success.
  record(entry) {
    if (!this.available || !this._emit) return false;
    if (this.finalized || this.incomplete) { this.omittedCount += 1; return false; }
    if (!this.accepting && !(this.closeRequested && this.finalSeq === null)) { this.omittedCount += 1; return false; }
    const data = {};
    let event = "";
    let at = "";
    try {
      const source = entry && typeof entry === "object" ? entry : null;
      event = source && typeof source.event === "string" ? source.event : "";
      for (const [key, value] of Object.entries(source)) {
        if (key === "event" || key === "at") continue;
        const kind = typeof value;
        if (value !== null && kind !== "string" && kind !== "number" && kind !== "boolean") {
          this._markIncomplete("payload-invalid");
          return false;
        }
        data[key] = value;
      }
      at = typeof source.at === "string" && source.at ? source.at : deviceTimestamp();
    } catch (error) {
      this._markIncomplete("payload-invalid");
      return false;
    }
    if (!event) {
      this._markIncomplete("payload-invalid");
      return false;
    }
    return this._emitFrame(event, data, at);
  }

  _emitFrame(event, data, at) {
    if (!this._emit) return false;
    let frame;
    try {
      frame = JSON.stringify({ v: 1, sessionId: this.id, seq: this.seq + 1, at, event, data });
    } catch (error) {
      this.serializationFailureCount += 1;
      this.errorCount += 1;
      this._markIncomplete("serialization-failed");
      return false;
    }
    const bytes = providerCaptureByteLength(frame);
    if (bytes > PROVIDER_CAPTURE_FRAME_LIMIT_BYTES) {
      this._markIncomplete("frame-over-limit");
      return false;
    }
    if (this.bytesWritten + bytes > this.maxBytes - this.reserve) {
      this._markIncomplete("session-byte-limit");
      return false;
    }
    try {
      this._emit(frame);
    } catch (error) {
      this._noteEmitFailure();
      return false;
    }
    this.seq += 1;
    this.bytesWritten += bytes;
    this.entryCount += 1;
    return true;
  }

  // Terminal frames (session-start/end/incomplete) use the full session ceiling
  // so the marker reserve is honored even at the byte limit. They share the
  // same sequence and byte accounting as normal frames.
  _emitTerminal(event, data) {
    if (!this._emit) return false;
    let frame;
    try {
      frame = JSON.stringify({ v: 1, sessionId: this.id, seq: this.seq + 1, at: deviceTimestamp(), event, data });
    } catch (error) {
      this.serializationFailureCount += 1;
      this.errorCount += 1;
      return false;
    }
    const bytes = providerCaptureByteLength(frame);
    if (bytes > PROVIDER_CAPTURE_FRAME_LIMIT_BYTES || this.bytesWritten + bytes > this.maxBytes) return false;
    try {
      this._emit(frame);
    } catch (error) {
      this._noteEmitFailure();
      return false;
    }
    this.seq += 1;
    this.bytesWritten += bytes;
    this.entryCount += 1;
    return true;
  }

  _noteEmitFailure() {
    this.errorCount += 1;
    this.available = false;
    this.unavailableReason = "emit-failed";
    if (!this.incomplete) {
      this.incomplete = true;
      this.incompleteReason = "emit-failed";
    }
  }

  _markIncomplete(reason) {
    if (this.incomplete) {
      this.omittedCount += 1;
      return;
    }
    this.incomplete = true;
    this.incompleteReason = reason;
    this.omittedCount += 1;
    this._emitTerminal("session-incomplete", { reason, observedBytes: this.bytesWritten });
  }

  requestClose() {
    this.closeRequested = true;
    this.accepting = false;
    if (this.pending === 0) this._scheduleFinalDrain();
    return this.summary();
  }

  _scheduleFinalDrain() {
    if (this.finalDrainScheduled || this.finalized) return;
    this.finalDrainScheduled = true;
    // Deferred one macrotask so already-admitted trailing telemetry (e.g. the
    // usage observation recorded right after a response settles) lands before
    // session-end; this is not a request-path wait and never blocks stop.
    window.setTimeout(() => {
      this.finalDrainScheduled = false;
      this._beginFinalDrain();
    }, 0);
  }

  _beginFinalDrain() {
    if (this.finalized || this.finalSeq !== null) return;
    const emitted = this._emitTerminal("session-end", { entryCount: this.entryCount, incomplete: this.incomplete });
    if (!emitted) {
      this._finalize(false, this.incomplete ? this.incompleteReason : "session-end-unavailable");
      return;
    }
    this.finalSeq = this.seq;
    this._ackTimer = window.setTimeout(() => this._finalize(false, "ack-timeout"), PROVIDER_CAPTURE_ACK_WINDOW_MS);
  }

  // Final valid acknowledgement: only a contiguous sequence for THIS session at
  // or past the emitted session-end completes the window. Invalid or future
  // acknowledgements fail closed and can never complete the session.
  acknowledge(sessionId, sequence) {
    if (String(sessionId || "") !== this.id) return { ok: false, reasonCode: "debug-session-mismatch" };
    const seq = Number(sequence);
    if (!Number.isInteger(seq) || seq < 1 || seq > this.seq) return { ok: false, reasonCode: "debug-sequence-invalid" };
    if (this.finalized) {
      return seq <= this.acknowledgedSeq
        ? { ok: true, sessionId: this.id, acknowledgedSeq: this.acknowledgedSeq, complete: this.completed }
        : { ok: false, reasonCode: "debug-session-finalized" };
    }
    if (seq > this.acknowledgedSeq) this.acknowledgedSeq = seq;
    if (this.finalSeq !== null && this.acknowledgedSeq >= this.finalSeq) this._finalize(!this.incomplete, "acknowledged");
    return { ok: true, sessionId: this.id, acknowledgedSeq: this.acknowledgedSeq, complete: this.completed };
  }

  detach() {
    this.accepting = false;
    this.closeRequested = true;
    if (!this.finalized) this._finalize(false, "collector-detached");
    return this.summary();
  }

  _finalize(complete, reason) {
    if (this.finalized) return;
    this.finalized = true;
    this.completed = Boolean(complete);
    this.accepting = false;
    if (!complete && !this.incomplete) {
      this.incomplete = true;
      this.incompleteReason = reason || "incomplete";
    }
    if (this._ackTimer !== null) {
      window.clearTimeout(this._ackTimer);
      this._ackTimer = null;
    }
    try {
      if (typeof this._onFinalize === "function") this._onFinalize(this.summary());
    } catch (error) {
      // Never propagate a finalize-callback failure to the provider path.
    }
  }

  summary() {
    return {
      sessionId: this.id,
      available: this.available,
      unavailableReason: this.available ? "" : this.unavailableReason,
      lifecycle: this.lifecycleState(),
      bytesWritten: this.bytesWritten,
      entryCount: this.entryCount,
      omittedCount: this.omittedCount,
      errorCount: this.errorCount,
      payloadOmittedCount: this.payloadOmittedCount,
      payloadIncompleteCount: this.payloadIncompleteCount,
      redactionFailureCount: this.redactionFailureCount,
      serializationFailureCount: this.serializationFailureCount,
      incomplete: this.incomplete,
      incompleteReason: this.incompleteReason,
      pending: this.pending,
      accepting: this.accepting,
      closed: this.finalized,
      completed: this.completed,
      startedAt: this.startedAt
    };
  }

  close() {
    return this.requestClose();
  }
}

function safeProviderCapture(sink, entry) {
  try {
    if (sink && typeof sink.record === "function") sink.record(entry);
  } catch (error) {
    // Logging failure must never propagate to the provider call path.
  }
}

// One immutable attempt context per generation/embedding attempt; the transport
// creates a distinct requestId for every request/post it starts. The session
// sink reference is shared (mutable writer) but the ID bindings are frozen.
function providerCaptureAttemptContext(root, operation) {
  if (!root || !root.sink) return null;
  return Object.freeze({
    workflowId: root.workflowId || null,
    attemptId: providerCaptureId("attempt"),
    operation: operation || root.operation || null,
    sink: root.sink
  });
}

// Native token usage normalization: provider field families are read with an
// explicit precedence (Responses field first, then Chat Completions, then
// legacy) and never summed. A missing field is UNKNOWN (null), never zero; a
// present finite field is preserved even when it is genuinely zero. Cached input
// is a subset detail of input and is never added to input again.
function aiTokenUsageField(usage, paths) {
  for (const path of paths) {
    const value = String(path).split(".").reduce((node, key) => (node == null ? undefined : node[key]), usage);
    if (value !== undefined && value !== null && Number.isFinite(Number(value))) return Number(value);
  }
  return null;
}

function normalizeAiTokenUsage(usage = {}) {
  const source = usage && typeof usage === "object" ? usage : {};
  const inputTokens = aiTokenUsageField(source, ["input_tokens", "prompt_tokens", "promptTokenCount"]);
  const outputTokens = aiTokenUsageField(source, ["output_tokens", "completion_tokens", "candidatesTokenCount"]);
  const reasoningTokens = aiTokenUsageField(source, ["output_tokens_details.reasoning_tokens", "output_tokens_details.thinking_tokens", "completion_tokens_details.reasoning_tokens", "thoughtsTokenCount"]);
  const cachedInputTokens = aiTokenUsageField(source, ["input_tokens_details.cached_tokens", "prompt_tokens_details.cached_tokens", "cache_read_input_tokens", "cachedContentTokenCount"]);
  const cacheWriteTokens = aiTokenUsageField(source, ["input_tokens_details.cache_write_tokens", "prompt_tokens_details.cache_write_tokens", "cache_creation_input_tokens", "cacheWritePromptTokenCount"]);
  const explicitTotal = aiTokenUsageField(source, ["total_tokens", "totalTokenCount"]);
  const totalTokens = explicitTotal !== null
    ? explicitTotal
    : (inputTokens !== null && outputTokens !== null ? inputTokens + outputTokens : null);
  const present = [inputTokens, outputTokens, reasoningTokens, cachedInputTokens, cacheWriteTokens, explicitTotal].some((value) => value !== null);
  return { inputTokens, outputTokens, reasoningTokens, cachedInputTokens, cacheWriteTokens, totalTokens, present };
}

function providerCaptureTransport(provider, request, captureContext, inner, state) {
  if (providerCaptureExcludedRequest(request, captureContext)) return;
  const sink = captureContext.sink;
  if (!sink || typeof sink.record !== "function") return;
  let admitted = true;
  if (typeof sink.beginRequest === "function") admitted = sink.beginRequest();
  if (admitted === false) return;
  let finishCalled = false;
  const finishRequest = () => {
    if (finishCalled) return;
    finishCalled = true;
    try {
      if (typeof sink.endRequest === "function") sink.endRequest();
    } catch (error) {
      // Never propagate.
    }
  };
  try {
    const url = String(request?.url || "");
    const method = String(request?.method || "GET").toUpperCase();
    const isPoll = method === "GET" && /\/responses\/[^/?#]+$/.test(url);
    const requestId = providerCaptureId("req");
    const base = {
      requestId,
      workflowId: captureContext.workflowId || null,
      attemptId: captureContext.attemptId || null,
      operation: captureContext.operation || null,
      provider
    };
    // Ephemeral per-request secrets (headers are never captured). The known
    // values are used only to redact the wire text before it is emitted.
    const knownSecrets = (Array.isArray(sink.knownSecrets) ? sink.knownSecrets : [])
      .concat(providerCaptureRequestCredentialValues(request));
    // Wire text is consumed only when it is ALREADY a string: response.json is
    // never accessed or parsed just for logging. The full URL is never emitted.
    safeProviderCapture(sink, Object.assign({}, base, {
      event: isPoll ? "poll_request" : "request",
      at: deviceTimestamp(),
      method,
      isPoll
    }));
    providerCaptureEmitWireText(sink, base, "request", request?.body, knownSecrets);
    let settled = false;
    const settle = (kind, value) => {
      if (settled) return;
      settled = true;
      try {
        if (kind === "response") {
          const status = Number.isFinite(Number(value?.status)) ? Number(value.status) : null;
          const urlId = isPoll ? decodeURIComponent((url.match(/\/responses\/([^/?#]+)$/) || [])[1] || "") : "";
          // Only values already available WITHOUT diagnostic parsing are
          // recorded: the poll URL id is known; provider/origin ids and usage
          // are resolved later from the sanitized response text by the external
          // evaluator. Null + correlationUnknown means "not available here",
          // never zero and never a guess.
          safeProviderCapture(sink, Object.assign({}, base, {
            event: isPoll ? "poll_response" : "response",
            at: deviceTimestamp(),
            status,
            isPoll,
            providerResponseId: null,
            polledResponseId: isPoll ? (urlId || null) : null,
            originRequestId: null,
            correlationUnknown: isPoll ? true : false,
            usageCumulative: isPoll,
            usageInputTokens: null,
            usageOutputTokens: null,
            usageCachedInputTokens: null,
            usageReasoningTokens: null,
            usageTotalTokens: null,
            late: Boolean(state && state.timedOut)
          }));
          providerCaptureEmitWireText(sink, base, "response", value?.text, knownSecrets);
        } else {
          const message = providerCaptureSafeText(String(value?.message || value || ""), knownSecrets);
          safeProviderCapture(sink, Object.assign({}, base, {
            event: isPoll ? "poll_error" : "error",
            at: deviceTimestamp(),
            code: value && value.code ? providerCaptureSafeText(String(value.code), knownSecrets).text : null,
            retryable: Boolean(value && value.retryable),
            message: message.ok ? message.text : null,
            messageOmitted: !message.ok,
            late: Boolean(state && state.timedOut)
          }));
        }
      } finally {
        finishRequest();
      }
    };
    // Observe the underlying request promise (not the raced promise): a late
    // settlement after a caller stop still belongs to this requestId and drains
    // to the same collector, but never alters the caller's outcome.
    inner.then(
      (value) => settle("response", value),
      (error) => settle("error", error)
    );
  } catch (error) {
    finishRequest();
  }
}

function requestProviderUrl(provider, request, captureContext = null) {
  const controller = typeof AbortController === "function" ? new AbortController() : null;
  const requestOptions = Object.assign({}, request);
  let removeUpstreamAbort = null;
  if (controller) {
    requestOptions.signal = controller.signal;
    if (request.signal?.aborted) controller.abort();
    else if (request.signal?.addEventListener) {
      const abortUpstream = () => controller.abort();
      request.signal.addEventListener("abort", abortUpstream, { once: true });
      removeUpstreamAbort = () => request.signal.removeEventListener?.("abort", abortUpstream);
    }
  }
  // No fixed provider request timeout: requests run until the provider
  // responds or the caller aborts. Upstream cancellation is still forwarded.
  const captureState = { timedOut: false };
  const inner = Promise.resolve().then(() => requestUrl(requestOptions));
  if (captureContext && captureContext.sink) {
    try {
      providerCaptureTransport(provider, request, captureContext, inner, captureState);
    } catch (error) {
      // Capture must never break the provider call path.
    }
  }
  return inner.finally(() => {
    if (removeUpstreamAbort) removeUpstreamAbort();
  });
}

function providerAdapterBaseUrl(settings = {}, provider = "") {
  const normalized = stableSupportedProvider(provider, "openrouter");
  if (normalized === "openrouter") return "https://openrouter.ai/api/v1";
  if (normalized === "anthropic") return "https://api.anthropic.com";
  const source = settings && typeof settings === "object" ? settings : {};
  const configured = normalized === "openwebui" ? source.openwebuiBaseUrl : source.customOpenAIBaseUrl;
  const allowInsecureHttp = normalized === "openwebui"
    ? source.openwebuiAllowInsecureHttp === true
    : source.customOpenAIAllowInsecureHttp === true;
  const raw = String(configured || "").trim();
  if (!raw) throw providerAdapterError(normalized, "provider-endpoint-missing", "Configure the provider base URL before testing it.");
  const schemeMatch = raw.match(/^([a-zA-Z][a-zA-Z0-9+.-]*):\/\//);
  const explicitScheme = schemeMatch ? schemeMatch[1].toLowerCase() : "";
  if (schemeMatch && explicitScheme !== "https" && explicitScheme !== "http") {
    throw providerAdapterError(normalized, "provider-endpoint-invalid", "The provider root uses an unsupported scheme; use an https:// provider root.");
  }
  if (explicitScheme === "http" && !allowInsecureHttp) {
    throw providerAdapterError(normalized, "provider-endpoint-insecure-http", "Explicit http:// provider roots are blocked unless insecure HTTP is explicitly allowed for this provider.");
  }
  let parsed;
  try {
    parsed = new URL(schemeMatch ? raw : `https://${raw}`);
  } catch {
    throw providerAdapterError(normalized, "provider-endpoint-invalid", "The saved provider base URL is invalid.");
  }
  if (parsed.protocol !== "https:" && parsed.protocol !== "http:") {
    throw providerAdapterError(normalized, "provider-endpoint-invalid", "The provider root uses an unsupported scheme; use an https:// provider root.");
  }
  if (parsed.protocol === "http:" && !allowInsecureHttp) {
    throw providerAdapterError(normalized, "provider-endpoint-insecure-http", "Explicit http:// provider roots are blocked unless insecure HTTP is explicitly allowed for this provider.");
  }
  if (parsed.username || parsed.password) {
    throw providerAdapterError(normalized, "provider-endpoint-invalid", "The provider root must exclude embedded credentials.");
  }
  if (parsed.search) {
    throw providerAdapterError(normalized, "provider-endpoint-invalid", "The provider root must exclude query strings.");
  }
  if (parsed.hash) {
    throw providerAdapterError(normalized, "provider-endpoint-invalid", "The provider root must exclude fragments.");
  }
  if (normalized === "openwebui") {
    // OpenWebUI's OpenAI-compatible endpoints live under <origin>/api; its
    // /v1 paths are the SPA catch-all, and /api/v1 aliases exist only on newer
    // builds. Treat a saved trailing '/v1' as the old broken migration output
    // and resolve the effective base at use time so no settings rewrite is
    // needed (the one-time migration is never re-run for migrated installs).
    let pathname = parsed.pathname.replace(/\/+$/, "");
    if (/\/v1$/i.test(pathname)) pathname = pathname.replace(/\/v1$/i, "");
    if (!/\/api$/i.test(pathname)) pathname = `${pathname}/api`;
    return `${parsed.origin}${pathname}`;
  }
  return parsed.toString().replace(/\/+$/, "");
}

function providerAdapterText(response = {}) {
  const choice = response?.choices?.[0] || {};
  const content = choice.message?.content ?? choice.text ?? "";
  if (Array.isArray(content)) return content.map((item) => item?.text || item?.content || "").join("");
  if (content && typeof content === "object") return String(content.text ?? content.content ?? "").trim();
  return String(content || "").trim();
}

// Obsidian's RequestUrlResponse.json getter parses the buffered body and
// throws on invalid JSON (HTML, SSE, plain-text errors). Read it without
// letting that throw escape so non-JSON bodies can be classified.
function safeProviderResponseJson(response = {}) {
  try {
    const json = response?.json;
    return json && typeof json === "object" ? json : null;
  } catch {
    return null;
  }
}

function isOpenAiSseText(text) {
  const value = String(text || "").replace(/^\uFEFF/, "").trimStart();
  if (value.startsWith("data:")) return true;
  return /(?:^|\n)\s*data:/.test(value);
}

// OpenWebUI (and any OpenAI-compatible server) may answer a buffered chat
// request with Server-Sent Events: `data: {chunk}\n\n` frames ending in
// `data: [DONE]`. Join the content deltas into one synthetic chat-completion
// JSON so providerAdapterText / recordAiTokenUsage / extractJsonPayload run
// unchanged. Frames without choices (arena/queued events) are skipped,
// reasoning_content is collected separately and never appended to the text,
// the last usage frame wins, and a frame carrying {error:{message}} becomes a
// typed stream error (providerAdapterError redacts Bearer-like values).
// T19/F2: carry model and id from the first frame that has them so the
// synthesized payload has identity fields for response tracking.
function parseOpenAiSseChatPayload(text, provider) {
  let content = "";
  let reasoning = "";
  let usage = null;
  let model = "";
  let id = "";
  for (const rawLine of String(text || "").split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line.startsWith("data:")) continue;
    const frameText = line.slice(5).trim();
    if (!frameText) continue;
    if (frameText === "[DONE]") break;
    let frame = null;
    try {
      frame = JSON.parse(frameText);
    } catch {
      continue;
    }
    if (!frame || typeof frame !== "object") continue;
    if (frame.error) {
      const message = typeof frame.error === "string" ? frame.error : frame.error?.message || frame.error?.code || "stream error";
      throw providerAdapterError(provider, "stream-error", String(message));
    }
    // Capture model/id from first frame that provides them
    if (!model && typeof frame.model === "string") model = frame.model;
    if (!id && typeof frame.id === "string") id = frame.id;
    const choice = Array.isArray(frame.choices) ? frame.choices[0] : null;
    if (!choice || typeof choice !== "object") continue;
    const delta = choice.delta && typeof choice.delta === "object" ? choice.delta : null;
    const message = choice.message && typeof choice.message === "object" ? choice.message : null;
    const contentPart = delta && delta.content !== undefined ? delta.content : message ? message.content : undefined;
    if (typeof contentPart === "string") content += contentPart;
    else if (Array.isArray(contentPart)) content += contentPart.map((item) => item?.text ?? item?.content ?? "").join("");
    const reasoningPart = delta && delta.reasoning_content !== undefined ? delta.reasoning_content : message ? message.reasoning_content : undefined;
    if (typeof reasoningPart === "string") reasoning += reasoningPart;
    if (frame.usage && typeof frame.usage === "object") usage = frame.usage;
  }
  const message = { content };
  if (reasoning) message.reasoning_content = reasoning;
  const payload = { choices: [{ message }] };
  if (model) payload.model = model;
  if (id) payload.id = id;
  if (usage) payload.usage = usage;
  return payload;
}

// Chat responses that already parse as JSON follow the historical path
// unchanged; only null/unparseable bodies whose text is SSE are converted.
function openAiCompatibleChatPayload(response = {}, provider = "") {
  const json = safeProviderResponseJson(response);
  if (json) return json;
  const text = String(response?.text ?? "");
  if (!isOpenAiSseText(text)) return json;
  return parseOpenAiSseChatPayload(text, provider);
}

function normalizeProviderEmbeddingRows(rows, expectedCount, expectedDimension = 0, provider = "provider") {
  if (!Array.isArray(rows) || rows.length !== expectedCount) throw providerAdapterError(provider, "embedding-count-mismatch", "The provider returned an unexpected embedding count.");
  const result = new Array(expectedCount);
  const seen = new Set();
  let dimension = 0;
  rows.forEach((row, position) => {
    const rawIndex = row && Object.prototype.hasOwnProperty.call(row, "index") ? Number(row.index) : position;
    if (!Number.isInteger(rawIndex) || rawIndex < 0 || rawIndex >= expectedCount || seen.has(rawIndex)) throw providerAdapterError(provider, "embedding-index-invalid", "The provider returned invalid or duplicate embedding indexes.");
    seen.add(rawIndex);
    const vector = Array.isArray(row?.embedding) ? row.embedding : Array.isArray(row?.values) ? row.values : null;
    if (!vector?.length || vector.some((value) => !Number.isFinite(Number(value)))) throw providerAdapterError(provider, "embedding-vector-invalid", "The provider returned a non-finite embedding vector.");
    if (!dimension) dimension = vector.length;
    if (vector.length !== dimension || (expectedDimension > 0 && vector.length !== expectedDimension)) {
      const dimensionError = providerAdapterError(provider, "embedding-dimension-mismatch", "The provider returned inconsistent embedding dimensions.");
      dimensionError.embeddingDimension = { expected: Number(expectedDimension) || 0, actual: vector.length };
      throw dimensionError;
    }
    result[rawIndex] = vector.map(Number);
  });
  if (result.some((vector) => !vector)) throw providerAdapterError(provider, "embedding-index-missing", "The provider omitted an embedding index.");
  return result;
}

function settingsDisclosure(containerEl, title, description = "", open = false, extraClass = "") {
  const classes = ["semantic-todoist-settings-disclosure", extraClass].filter(Boolean).join(" ");
  const disclosure = containerEl.createEl("details", { cls: classes });
  disclosure.open = Boolean(open);
  disclosure.createEl("summary", { text: title });
  if (description) disclosure.createDiv({ cls: "semantic-todoist-settings-disclosure-description", text: description });
  return disclosure.createDiv({ cls: "semantic-todoist-settings-disclosure-body" });
}

function stableProviderLabel(provider) {
  return STABLE_PROVIDER_LABELS[stableSupportedProvider(provider)] || "OpenRouter";
}

function customOpenAIConnectionDisplayName(settings = {}) {
  const title = typeof settings?.customOpenAIConnectionTitle === "string" ? settings.customOpenAIConnectionTitle.trim() : "";
  return title || "Custom OpenAI-compatible";
}

function providerCatalogModels(settings, provider, embedding = false) {
  const normalized = stableSupportedProvider(provider);
  const catalogs = embedding ? settings.providerEmbeddingModels : settings.providerGenerationModels;
  const catalog = Array.isArray(catalogs?.[normalized]) ? catalogs[normalized] : [];
  const legacy = embedding
    ? {
      openai: settings.availableEmbeddingModels,
      gemini: settings.availableGeminiEmbeddingModels,
      openrouter: settings.availableOpenRouterEmbeddingModels,
      openwebui: settings.availableOpenWebUIEmbeddingModels,
      customopenai: settings.availableCustomOpenAIEmbeddingModels
    }[normalized]
    : {
      openai: settings.availableChatModels,
      gemini: settings.availableGeminiModels,
      openrouter: settings.availableOpenRouterModels,
      openwebui: settings.availableOpenWebUIModels,
      customopenai: settings.availableCustomOpenAIModels
    }[normalized];
  return uniqueValues((catalog || []).concat(legacy || []).map((value) => String(value || "").trim()).filter(Boolean));
}

function providerDropdownOptions(provider, embedding = false) {
  return (embedding ? ["openai", "gemini", "openrouter", "openwebui", "customopenai"] : SUPPORTED_AI_PROVIDERS)
    .map((value) => ({ value, label: stableProviderLabel(value) }));
}

function providerTextSetting(containerEl, name, desc, plugin, key, options = {}) {
  new Setting(containerEl).setName(name).setDesc(desc || "").addText((text) => {
    text.setValue(String(plugin.settings[key] || "")).onChange(async (value) => {
      if (options.providerRoot) {
        if (!String(value || "").trim()) {
          plugin.settings[key] = "";
          await plugin.saveSettings();
          return;
        }
        let savedRoot;
        try {
          savedRoot = providerAdapterBaseUrl(Object.assign({}, plugin.settings, { [key]: value }), options.providerRoot);
        } catch {
          return;
        }
        plugin.settings[key] = savedRoot;
        await plugin.saveSettings();
        return;
      }
      plugin.settings[key] = options.url ? normalizeHttpsUrl(value) : value;
      await plugin.saveSettings();
    });
  });
}

function ephemeralSecretSetting(containerEl, name, desc, plugin, property) {
  new Setting(containerEl).setName(name).setDesc(desc || "").addText((text) => {
    text.inputEl.type = "password";
    text.setValue(String(plugin[property] || "")).onChange((value) => {
      plugin[property] = String(value || "");
    });
  });
}

function aiProviderSetting(containerEl, plugin, refreshDisplay, tab = null) {
  const current = normalizeAiProvider(tab?.providerViewProvider || plugin.settings.aiModelProvider, "openrouter");
  new Setting(containerEl)
    .setName("Provider connection to show")
    .setDesc("Display-only selection. It does not change routing, embeddings, or saved settings.")
    .addDropdown((dropdown) => {
      for (const option of providerDropdownOptions()) dropdown.addOption(option.value, option.label);
      dropdown.setValue(current).onChange((value) => {
        if (tab) tab.providerViewProvider = stableSupportedProvider(value, current);
        if (refreshDisplay) refreshDisplay();
      });
    });
}

function providerConnectionDisclosure(containerEl, plugin, provider) {
  const normalized = stableSupportedProvider(provider, "openrouter");
  const connectionLabel = normalized === "customopenai" ? customOpenAIConnectionDisplayName(plugin.settings) : stableProviderLabel(normalized);
  const body = settingsDisclosure(containerEl, `${connectionLabel} connection`, "Only the selected connection is shown. Refresh and test actions are explicit.", true, "semantic-todoist-provider-connection");
  if (normalized === "openai") {
    secretSetting(body, "OpenAI API key", plugin, "openaiApiKey");
  } else if (normalized === "gemini") {
    secretSetting(body, "Google Gemini API key", plugin, "googleApiKey");
  } else if (normalized === "openrouter") {
    secretSetting(body, "OpenRouter API key", plugin, "openrouterApiKey");
    providerTextSetting(body, "OpenRouter default model", "Optional saved model used when the provider catalog is empty.", plugin, "openrouterDefaultModel");
  } else if (normalized === "anthropic") {
    secretSetting(body, "Anthropic API key", plugin, "anthropicApiKey");
  } else if (normalized === "openwebui") {
    providerTextSetting(body, "OpenWebUI base URL", "Use your server root; /api is added. No endpoint is inferred from a model name.", plugin, "openwebuiBaseUrl", { providerRoot: "openwebui" });
    toggleSetting(body, "Allow insecure HTTP", "Off by default. Allows an explicit http:// root only for this OpenWebUI connection; loopback hosts are not exempt.", plugin, "openwebuiAllowInsecureHttp");
    secretSetting(body, "OpenWebUI API key or token", plugin, "openwebuiApiKey");
    dropdownSettingWithDesc(body, "Authentication mode", "Use a saved token, or enter an ephemeral login password only for an explicit provider test.", plugin, "openwebuiAuthMode", ["api-key", "login"]);
    ephemeralSecretSetting(body, "Login password (not saved)", "Held only in memory until the explicit provider test completes.", plugin, "openwebuiLoginPassword");
  } else {
    providerTextSetting(body, "Custom connection title", "Optional display-only label for this connection. It never changes routing, credentials, catalogs, or requests.", plugin, "customOpenAIConnectionTitle");
    providerTextSetting(body, "Custom OpenAI-compatible base URL", "Saved HTTPS API root. No endpoint is inferred from a model name.", plugin, "customOpenAIBaseUrl", { providerRoot: "customopenai" });
    toggleSetting(body, "Allow insecure HTTP", "Off by default. Allows an explicit http:// root only for this custom connection; loopback hosts are not exempt.", plugin, "customOpenAIAllowInsecureHttp");
    secretSetting(body, "Custom OpenAI-compatible API key", plugin, "customOpenAIApiKey");
    providerTextSetting(body, "Custom default model", "Optional model ID used when the provider catalog is empty.", plugin, "customOpenAIModel");
  }
  new Setting(body).setName("Validate connection").setDesc("Explicitly checks this connection's credentials by loading its model list; never runs automatically.").addButton((button) => button.setButtonText("Validate connection").onClick(async () => {
    button.setDisabled(true);
    try {
      const result = await plugin.validateProviderConnection(normalized);
      new Notice(`${stableProviderLabel(normalized)} connection OK: loaded ${result.modelsLoaded} models.`);
    } catch (error) {
      const message = error && error.message ? String(error.message) : String(error || "Validation failed.");
      new Notice(`Validation failed: ${redactSecrets(message)}`);
    } finally {
      button.setDisabled(false);
    }
  }));
  return body;
}

function renderProviderConnectionSettings(containerEl, plugin, tab = null) {
  const provider = tab?.providerViewProvider || plugin.settings.aiModelProvider || "openrouter";
  providerConnectionDisclosure(containerEl, plugin, provider);
}

function stableSharedReference(settings, role) {
  const normalized = normalizeStableSettings(settings);
  return role === "fallback" ? normalized.sharedGenerationFallback : normalized.sharedGenerationPrimary;
}

function stableUiOperationReference(settings, operation, role) {
  const normalized = normalizeStableSettings(settings);
  return normalized.aiOperationModels?.[operation]?.[role] || (role === "fallback" ? normalized.sharedGenerationFallback : normalized.sharedGenerationPrimary);
}

async function saveSharedReferenceField(plugin, role, field, value) {
  const current = stableSharedReference(plugin.settings, role);
  const next = stableReference(Object.assign({}, current, { [field]: value }), current);
  if (role === "fallback") {
    plugin.settings.sharedGenerationFallback = next;
    plugin.settings.fallbackAiModelProvider = next.provider;
    plugin.settings.chatFallbackModel = next.model;
    plugin.settings.chatFallbackReasoningEffort = next.reasoningEffort;
  } else {
    plugin.settings.sharedGenerationPrimary = next;
    plugin.settings.aiModelProvider = next.provider;
    plugin.settings.chatModel = next.model;
    plugin.settings.chatReasoningEffort = next.reasoningEffort;
  }
  await plugin.saveSettings();
}

async function saveOperationReferenceField(plugin, operation, role, field, value) {
  const current = stableUiOperationReference(plugin.settings, operation, role);
  const operations = cloneStableValue(plugin.settings.aiOperationModels || {});
  const row = Object.assign({}, operations[operation] || {});
  row[role] = stableReference(Object.assign({}, current, { [field]: value }), current);
  operations[operation] = row;
  plugin.settings.aiOperationModels = operations;
  await plugin.saveSettings();
}

// Fixed provider-group display order for every searchable model combobox.
// Gemini leads so overlapping model IDs stay disambiguated by group order.
const MODEL_COMBOBOX_PROVIDER_ORDER = Object.freeze(["gemini", "openai", "openrouter", "openwebui", "customopenai", "anthropic"]);

function modelComboboxDisplayName(provider, model) {
  return model ? `${stableProviderLabel(provider)}: ${model}` : "Provider default";
}

function modelComboboxGroups(settings, options = {}) {
  const allowed = Array.isArray(options.providers) && options.providers.length ? options.providers : MODEL_COMBOBOX_PROVIDER_ORDER;
  return MODEL_COMBOBOX_PROVIDER_ORDER
    .filter((provider) => allowed.includes(provider))
    .map((provider) => ({
      provider,
      label: stableProviderLabel(provider),
      models: providerCatalogModels(settings, provider, options.embedding === true).slice().sort((a, b) =>
        modelComboboxDisplayName(provider, a).localeCompare(modelComboboxDisplayName(provider, b), undefined, { sensitivity: "base" }))
    }));
}

// Settings keys a model combobox selection may rewrite through its save
// callback. Snapshotted before the save so a rejected save can restore the
// in-memory reference this helper owns.
const MODEL_COMBOBOX_OWNED_SETTINGS_KEYS = Object.freeze([
  "sharedGenerationPrimary",
  "sharedGenerationFallback",
  "aiModelProvider",
  "chatModel",
  "chatReasoningEffort",
  "fallbackAiModelProvider",
  "chatFallbackModel",
  "chatFallbackReasoningEffort",
  "aiOperationModels",
  "embeddingModelReference",
  "embeddingProvider",
  "embeddingModel",
  "chatWebSearchProvider",
  "chatWebSearchModel"
]);

function snapshotModelComboboxSettings(settings) {
  const snapshot = {};
  if (settings && typeof settings === "object") {
    for (const key of MODEL_COMBOBOX_OWNED_SETTINGS_KEYS) snapshot[key] = settings[key];
  }
  return snapshot;
}

function restoreModelComboboxSettings(settings, snapshot) {
  if (settings && typeof settings === "object" && snapshot && typeof snapshot === "object") {
    for (const key of MODEL_COMBOBOX_OWNED_SETTINGS_KEYS) {
      if (Object.prototype.hasOwnProperty.call(snapshot, key)) settings[key] = snapshot[key];
    }
  }
}

function notifyModelComboboxSaveError(error) {
  try {
    const message = error && error.message ? String(error.message) : String(error || "unknown error");
    if (typeof Notice === "function") new Notice(`Could not save model selection: ${message}`);
  } catch (noticeError) { /* label-only fake DOM or notice failure */ }
}

function parseModelComboboxManual(text, allowedProviders) {
  const raw = String(text || "").trim();
  const separator = raw.indexOf(":");
  if (separator <= 0) return null;
  const providerText = raw.slice(0, separator).trim().toLowerCase();
  const model = raw.slice(separator + 1).trim();
  if (!model) return null;
  const allowed = Array.isArray(allowedProviders) && allowedProviders.length ? allowedProviders : MODEL_COMBOBOX_PROVIDER_ORDER;
  const provider = MODEL_COMBOBOX_PROVIDER_ORDER
    .filter((candidate) => allowed.includes(candidate))
    .find((candidate) => candidate === providerText || stableProviderLabel(candidate).toLowerCase() === providerText);
  return provider ? { provider, model } : null;
}

async function saveSharedModelReference(plugin, role, provider, model) {
  const current = stableSharedReference(plugin.settings, role);
  const next = stableReference({ provider, model, reasoningEffort: current.reasoningEffort }, current);
  if (role === "fallback") {
    plugin.settings.sharedGenerationFallback = next;
    plugin.settings.fallbackAiModelProvider = next.provider;
    plugin.settings.chatFallbackModel = next.model;
    plugin.settings.chatFallbackReasoningEffort = next.reasoningEffort;
  } else {
    plugin.settings.sharedGenerationPrimary = next;
    plugin.settings.aiModelProvider = next.provider;
    plugin.settings.chatModel = next.model;
    plugin.settings.chatReasoningEffort = next.reasoningEffort;
  }
  await plugin.saveSettings();
}

async function saveOperationModelReference(plugin, operation, role, provider, model) {
  const current = stableUiOperationReference(plugin.settings, operation, role);
  const operations = cloneStableValue(plugin.settings.aiOperationModels || {});
  const row = Object.assign({}, operations[operation] || {});
  row[role] = stableReference({ provider, model, reasoningEffort: current.reasoningEffort }, current);
  operations[operation] = row;
  plugin.settings.aiOperationModels = operations;
  await plugin.saveSettings();
}

function setComboboxAttribute(element, key, value) {
  try {
    if (element && typeof element.setAttribute === "function") element.setAttribute(key, value);
    else if (element && typeof element.setAttr === "function") element.setAttr(key, value);
  } catch (error) { /* label-only fake DOM without attributes */ }
}

function removeComboboxAttribute(element, key) {
  try {
    if (element && typeof element.removeAttribute === "function") element.removeAttribute(key);
  } catch (error) { /* label-only fake DOM without attributes */ }
}

function addComboboxClass(element, value) {
  try {
    if (element && element.classList && typeof element.classList.add === "function") element.classList.add(value);
    else if (element && typeof element.addClass === "function") element.addClass(value);
  } catch (error) { /* label-only fake DOM without classes */ }
}

function onComboboxEvent(element, type, handler) {
  try {
    if (element && typeof element.addEventListener === "function") element.addEventListener(type, handler);
  } catch (error) { /* label-only fake DOM without events */ }
}

let modelComboboxSequence = 0;

// Shared provider-scoped accessible input/listbox combobox for model
// references. It filters only the already-loaded catalog locally, keeps the
// saved/manual value visible in the closed control (even when absent from
// every catalog), excludes inaccessible saved values from popup choices,
// saves only an explicit valid option/click/Enter selection, and never
// refreshes catalogs or calls a provider while rendering, typing, filtering,
// or selecting.
function modelComboboxSetting(containerEl, name, desc, plugin, config = {}) {
  const groups = Array.isArray(config.groups) ? config.groups : [];
  const allowedProviders = Array.isArray(config.allowedProviders) && config.allowedProviders.length
    ? config.allowedProviders.slice()
    : MODEL_COMBOBOX_PROVIDER_ORDER.slice();
  const includeDefault = config.includeDefault === true;
  const defaultProvider = stableSupportedProvider(config.defaultProvider, allowedProviders[0]);
  const onSelect = config.onSelect;
  const refreshDisplay = typeof config.refreshDisplay === "function" ? config.refreshDisplay : null;
  let currentSelection = config.current && typeof config.current === "object"
    ? { provider: stableSupportedProvider(config.current.provider, allowedProviders[0]), model: String(config.current.model || "") }
    : null;
  const comboboxId = `semantic-todoist-model-combobox-${(modelComboboxSequence += 1)}`;
  const setting = new Setting(containerEl).setName(name).setDesc(desc || "");
  setting.settingEl.addClass("semantic-todoist-model-combobox-setting");
  let comboboxInput = null;
  let comboboxBrowse = null;
  let committed = String(config.inputValue || "");
  let popup = null;
  let highlightIndex = -1;
  let visibleEntries = [];
  let manualEntry = null;
  let documentHandler = null;
  let popupRepositionListeners = null;
  let popupRepositionPending = false;

  setting.addText((text) => {
    const input = text.inputEl;
    comboboxInput = input;
    function pickerDocument() {
      try {
        if (input && input.ownerDocument) return input.ownerDocument;
      } catch (error) { /* label-only */ }
      return typeof document !== "undefined" ? document : null;
    }
    function pickerWindow() {
      const pickerDoc = pickerDocument();
      try {
        if (pickerDoc && pickerDoc.defaultView) return pickerDoc.defaultView;
      } catch (error) { /* label-only */ }
      return typeof window !== "undefined" ? window : null;
    }
    addComboboxClass(input, "semantic-todoist-model-combobox-input");
    setComboboxAttribute(input, "role", "combobox");
    setComboboxAttribute(input, "aria-label", config.ariaLabel || name);
    setComboboxAttribute(input, "aria-autocomplete", "list");
    setComboboxAttribute(input, "aria-expanded", "false");
    setComboboxAttribute(input, "aria-controls", `${comboboxId}-listbox`);
    text.setValue(committed);

    function describeSelection(provider, model) {
      return modelComboboxDisplayName(provider, model);
    }

    function isCurrentSelection(provider, model) {
      if (!currentSelection) return false;
      return stableSupportedProvider(provider, allowedProviders[0]) === currentSelection.provider
        && String(model || "") === currentSelection.model;
    }

    function closePopup() {
      detachPopupRepositionListeners();
      const closeDocument = pickerDocument();
      if (documentHandler && closeDocument && typeof closeDocument.removeEventListener === "function") {
        try { closeDocument.removeEventListener("mousedown", documentHandler); } catch (error) { /* label-only */ }
      }
      documentHandler = null;
      if (popup && typeof popup.remove === "function") {
        try { popup.remove(); } catch (error) { /* label-only */ }
      }
      popup = null;
      highlightIndex = -1;
      visibleEntries = [];
      manualEntry = null;
      setComboboxAttribute(input, "aria-expanded", "false");
      if (comboboxBrowse) setComboboxAttribute(comboboxBrowse, "aria-expanded", "false");
      removeComboboxAttribute(input, "aria-activedescendant");
    }

    function cancelPopup() {
      if (!popup) return;
      try { input.value = committed; } catch (error) { /* label-only */ }
      closePopup();
    }

    function renderPopup() {
      if (!popup) return;
      const renderDocument = pickerDocument();
      if (!renderDocument) return;
      while (popup.children && popup.children.length) {
        try { popup.removeChild(popup.children[0]); } catch (error) { break; }
      }
      const query = String(input.value == null ? "" : input.value);
      const unfiltered = query === committed;
      const needle = query.trim().toLowerCase();
      const entries = [];
      manualEntry = null;
      if (includeDefault && (!needle || unfiltered || "provider default".includes(needle))) {
        entries.push({ provider: defaultProvider, model: "", label: "Provider default", manual: false, isDefault: true });
      }
      for (const group of groups) {
        const matches = group.models.filter((model) => {
          if (unfiltered || !needle) return true;
          return describeSelection(group.provider, model).toLowerCase().includes(needle);
        });
        if (!matches.length) continue;
        const header = renderDocument.createElement("div");
        header.className = "semantic-todoist-model-combobox-group";
        setComboboxAttribute(header, "role", "presentation");
        header.textContent = group.label;
        popup.appendChild(header);
        for (const model of matches) {
          entries.push({ provider: group.provider, model, label: describeSelection(group.provider, model), manual: false, isDefault: false });
        }
      }
      const manual = parseModelComboboxManual(query, allowedProviders);
      // A manual row for the already-saved reference is never offered: the
      // saved value stays visible in the closed control but is excluded from
      // popup choices, and re-entering it cannot produce a redundant save.
      if (manual && !isCurrentSelection(manual.provider, manual.model)) {
        manualEntry = { provider: manual.provider, model: manual.model, label: describeSelection(manual.provider, manual.model), manual: true, isDefault: false };
        entries.push(manualEntry);
      }
      if (!entries.length) {
        const empty = renderDocument.createElement("div");
        empty.className = "semantic-todoist-model-combobox-empty";
        setComboboxAttribute(empty, "role", "presentation");
        empty.textContent = "No matching models. Type provider:model for a manual selection.";
        popup.appendChild(empty);
      }
      visibleEntries = entries;
      highlightIndex = -1;
      removeComboboxAttribute(input, "aria-activedescendant");
      entries.forEach((entry, index) => {
        entry.id = `${comboboxId}-option-${index}`;
        const option = renderDocument.createElement("div");
        option.className = "semantic-todoist-model-combobox-option";
        setComboboxAttribute(option, "role", "option");
        setComboboxAttribute(option, "id", entry.id);
        setComboboxAttribute(option, "aria-selected", "false");
        option.textContent = entry.label;
        onComboboxEvent(option, "click", () => { commitSelection(entry); });
        entry.element = option;
        popup.appendChild(option);
      });
    }

    function setPopupGeometry(top, maxHeight, left, width) {
      try {
        popup.style.position = "fixed";
        popup.style.left = `${Math.max(0, Math.round(left || 0))}px`;
        popup.style.width = `${Math.max(0, Math.round(width || 0))}px`;
        popup.style.right = "auto";
        popup.style.top = `${Math.max(0, Math.round(top))}px`;
        popup.style.maxHeight = `${Math.max(44, Math.round(maxHeight))}px`;
        popup.style.zIndex = "1000";
      } catch (error) { /* label-only */ }
    }

    function positionPopup() {
      if (!popup) return;
      const pickerView = pickerWindow();
      const viewportHeight = pickerView && pickerView.innerHeight ? Number(pickerView.innerHeight) : 600;
      let inputTop = 0;
      let inputBottom = 0;
      let inputLeft = 0;
      let inputWidth = 0;
      try {
        const rect = input && typeof input.getBoundingClientRect === "function" ? input.getBoundingClientRect() : null;
        if (rect) {
          if (typeof rect.top === "number") inputTop = rect.top;
          if (typeof rect.bottom === "number") inputBottom = rect.bottom;
          if (typeof rect.left === "number") inputLeft = rect.left;
          if (typeof rect.width === "number") inputWidth = rect.width;
        }
      } catch (error) { /* label-only */ }
      const naturalBelow = inputBottom + 4;
      const spaceBelow = viewportHeight - naturalBelow - 8;
      const spaceAbove = inputTop - 8;
      // Flip above the input when there is not enough room below but more
      // room above, so the popup never overflows the settings viewport.
      if (spaceBelow < 96 && spaceAbove > spaceBelow) {
        const maxAbove = Math.max(44, Math.min(260, spaceAbove - 4));
        setPopupGeometry(Math.max(0, inputTop - 4 - maxAbove), maxAbove, inputLeft, inputWidth);
        return;
      }
      const top = Math.max(0, Math.min(naturalBelow, viewportHeight - 52));
      setPopupGeometry(top, Math.max(44, Math.min(260, viewportHeight - top - 8)), inputLeft, inputWidth);
    }

    function attachDocumentHandler() {
      const handlerDocument = pickerDocument();
      if (documentHandler || !handlerDocument || typeof handlerDocument.addEventListener !== "function") return;
      documentHandler = (event) => {
        if (!popup) return;
        const target = event ? event.target : null;
        if (target === input) return;
        try {
          if (target && popup.contains(target)) return;
        } catch (error) { /* label-only */ }
        cancelPopup();
      };
      try { handlerDocument.addEventListener("mousedown", documentHandler); } catch (error) { /* label-only */ }
    }

    function popupInputVisible() {
      let rect = null;
      try {
        rect = input && typeof input.getBoundingClientRect === "function" ? input.getBoundingClientRect() : null;
      } catch (error) { /* label-only */ }
      if (!rect) return true;
      const pickerView = pickerWindow();
      const viewportHeight = pickerView && pickerView.innerHeight ? Number(pickerView.innerHeight) : 600;
      // A detached or fully scrolled-away input has no visible rect; close
      // rather than leave the popup floating over unrelated settings rows.
      if (!(rect.bottom > 0) || !(rect.top < viewportHeight)) return false;
      const scroller = semanticSettingsScroller(containerEl);
      if (scroller && typeof scroller.getBoundingClientRect === "function") {
        try {
          const scrollerRect = scroller.getBoundingClientRect();
          if (scrollerRect && Number.isFinite(scrollerRect.top) && Number.isFinite(scrollerRect.bottom)
            && (rect.bottom <= scrollerRect.top || rect.top >= scrollerRect.bottom)) return false;
        } catch (error) { /* label-only */ }
      }
      return true;
    }

    function repositionPopup() {
      if (!popup) return;
      if (!popupInputVisible()) { cancelPopup(); return; }
      positionPopup();
    }

    function schedulePopupReposition() {
      if (!popup || popupRepositionPending) return;
      popupRepositionPending = true;
      const pickerView = pickerWindow();
      if (pickerView && typeof pickerView.requestAnimationFrame === "function") {
        try {
          pickerView.requestAnimationFrame(() => {
            popupRepositionPending = false;
            repositionPopup();
          });
          return;
        } catch (error) { /* label-only */ }
      }
      // No animation frame available (fake DOM or bare popout view): reposition now.
      popupRepositionPending = false;
      repositionPopup();
    }

    function attachPopupRepositionListeners() {
      if (popupRepositionListeners) return;
      popupRepositionListeners = [];
      const ownerDocument = pickerDocument();
      const ownerWindow = pickerWindow();
      const addListener = (target, type, options) => {
        if (!target || typeof target.addEventListener !== "function") return;
        try {
          target.addEventListener(type, schedulePopupReposition, options);
          popupRepositionListeners.push({ target, type, options });
        } catch (error) { /* label-only */ }
      };
      // Capture-phase scroll on the owner document sees scrolls of the
      // settings pane and every other ancestor, including pop-out windows.
      addListener(ownerDocument, "scroll", true);
      addListener(ownerWindow, "resize");
      const visualViewport = ownerWindow ? ownerWindow.visualViewport : null;
      if (visualViewport) {
        addListener(visualViewport, "resize");
        addListener(visualViewport, "scroll");
      }
    }

    function detachPopupRepositionListeners() {
      const listeners = popupRepositionListeners;
      popupRepositionListeners = null;
      popupRepositionPending = false;
      if (!listeners) return;
      for (const listener of listeners) {
        try { listener.target.removeEventListener(listener.type, schedulePopupReposition, listener.options); } catch (error) { /* label-only */ }
      }
    }

    function openPopup() {
      const openDocument = pickerDocument();
      if (!openDocument || typeof openDocument.createElement !== "function" || !openDocument.body) return;
      if (!popup) {
        popup = openDocument.createElement("div");
        popup.className = "semantic-todoist-model-combobox-results";
        setComboboxAttribute(popup, "role", "listbox");
        setComboboxAttribute(popup, "id", `${comboboxId}-listbox`);
        setComboboxAttribute(popup, "aria-label", `${name} results`);
        onComboboxEvent(popup, "mousedown", (event) => { if (event && event.preventDefault) event.preventDefault(); });
        openDocument.body.appendChild(popup);
        setComboboxAttribute(input, "aria-expanded", "true");
        if (comboboxBrowse) setComboboxAttribute(comboboxBrowse, "aria-expanded", "true");
        attachDocumentHandler();
        attachPopupRepositionListeners();
      }
      renderPopup();
      positionPopup();
    }

    function setHighlight(index) {
      if (!visibleEntries.length) { highlightIndex = -1; return; }
      highlightIndex = ((index % visibleEntries.length) + visibleEntries.length) % visibleEntries.length;
      visibleEntries.forEach((entry, position) => {
        if (!entry.element) return;
        setComboboxAttribute(entry.element, "aria-selected", position === highlightIndex ? "true" : "false");
        if (position === highlightIndex) {
          setComboboxAttribute(input, "aria-activedescendant", entry.id);
          if (entry.element.scrollIntoView) {
            try { entry.element.scrollIntoView({ block: "nearest" }); } catch (error) { /* label-only */ }
          }
        }
      });
    }

    function moveHighlight(delta) {
      if (!popup || !visibleEntries.length) return;
      if (highlightIndex < 0) setHighlight(delta > 0 ? 0 : visibleEntries.length - 1);
      else setHighlight(highlightIndex + delta);
    }

    async function commitSelection(entry) {
      if (!entry || (!entry.model && !entry.isDefault)) return;
      const provider = stableSupportedProvider(entry.provider, allowedProviders[0]);
      const model = String(entry.model || "");
      // Re-entering the already-saved reference is a no-op: close without a
      // redundant save.
      if (isCurrentSelection(provider, model)) {
        cancelPopup();
        return;
      }
      const previousCommitted = committed;
      const settingsSnapshot = snapshotModelComboboxSettings(plugin.settings);
      // Transactional from the combobox's perspective: the closed value is
      // only published after the existing save callback succeeds. A rejected
      // save restores the prior value and the owned in-memory reference.
      try {
        await onSelect(provider, model);
      } catch (error) {
        restoreModelComboboxSettings(plugin.settings, settingsSnapshot);
        try { input.value = previousCommitted; } catch (labelError) { /* label-only */ }
        closePopup();
        notifyModelComboboxSaveError(error);
        return;
      }
      try {
        committed = modelComboboxDisplayName(provider, model);
        currentSelection = { provider, model };
        try { input.value = committed; } catch (labelError) { /* label-only */ }
        closePopup();
        if (refreshDisplay) refreshDisplay();
      } catch (error) {
        notifyModelComboboxSaveError(error);
      }
    }

    async function commitFromKeyboard() {
      if (!popup) return;
      if (highlightIndex >= 0 && visibleEntries[highlightIndex]) {
        await commitSelection(visibleEntries[highlightIndex]);
        return;
      }
      if (manualEntry) {
        await commitSelection(manualEntry);
        return;
      }
      // Only an explicitly highlighted/clicked catalog option or a parsed
      // provider-key/human-label provider:model manual row may save. Bare
      // model IDs — even unique ones — are never committed from free text.
      // Re-entering the saved value just closes the popup without saving.
      const query = String(input.value == null ? "" : input.value);
      if (query === committed) {
        cancelPopup();
        return;
      }
      const reparsed = parseModelComboboxManual(query, allowedProviders);
      if (reparsed && isCurrentSelection(reparsed.provider, reparsed.model)) {
        cancelPopup();
      }
    }

    onComboboxEvent(input, "focus", () => { openPopup(); });
    onComboboxEvent(input, "click", () => { if (!popup) openPopup(); });
    onComboboxEvent(input, "input", () => { openPopup(); });
    onComboboxEvent(input, "blur", () => {
      setTimeout(() => {
        if (!popup) return;
        const blurDocument = pickerDocument();
        const active = blurDocument ? blurDocument.activeElement : null;
        if (active && (active === input)) return;
        try {
          if (active && popup.contains(active)) return;
        } catch (error) { /* label-only */ }
        cancelPopup();
      }, 0);
    });
    onComboboxEvent(input, "keydown", (event) => {
      const key = event ? event.key || "" : "";
      if (key === "Escape") {
        if (event.preventDefault) event.preventDefault();
        cancelPopup();
      } else if (key === "Enter") {
        if (event.preventDefault) event.preventDefault();
        commitFromKeyboard();
      } else if (key === "ArrowDown") {
        if (event.preventDefault) event.preventDefault();
        openPopup();
        moveHighlight(1);
      } else if (key === "ArrowUp") {
        if (event.preventDefault) event.preventDefault();
        openPopup();
        moveHighlight(-1);
      }
    });
  });
  setting.addButton((button) => {
    button.setButtonText("Browse").onClick(() => {
      try {
        if (comboboxInput && typeof comboboxInput.focus === "function") comboboxInput.focus();
      } catch (error) { /* label-only */ }
    });
    const browseEl = button && button.buttonEl ? button.buttonEl : null;
    if (browseEl) {
      addComboboxClass(browseEl, "semantic-todoist-model-combobox-browse");
      setComboboxAttribute(browseEl, "aria-label", "Browse " + name + " models");
      setComboboxAttribute(browseEl, "aria-expanded", "false");
      comboboxBrowse = browseEl;
    }
  });
  return setting;
}

function referenceDropdownSetting(containerEl, name, desc, plugin, options = {}) {
  const { operation = "", role = "primary", field = "provider", shared = false, refreshDisplay = null } = options;
  const current = shared ? stableSharedReference(plugin.settings, role) : stableUiOperationReference(plugin.settings, operation, role);
  if (field === "model") {
    // Scope the catalog to the provider selected in this row's sibling
    // provider dropdown. The stored reference keeps its own provider/model
    // pair, so a saved model outside the scoped catalog stays visible.
    const storedProvider = String(current.provider || "").trim().toLowerCase();
    const canonicalProvider = STABLE_SUPPORTED_PROVIDER_ALIASES[storedProvider] || storedProvider;
    const rowProvider = SUPPORTED_AI_PROVIDERS.includes(canonicalProvider) ? stableSupportedProvider(canonicalProvider, "") : "";
    const scopedProviders = rowProvider ? [rowProvider] : MODEL_COMBOBOX_PROVIDER_ORDER.slice();
    return modelComboboxSetting(containerEl, name, desc, plugin, {
      inputValue: current.model ? `${stableProviderLabel(current.provider)}: ${current.model}` : "",
      groups: modelComboboxGroups(plugin.settings, { embedding: false, providers: scopedProviders }),
      allowedProviders: scopedProviders,
      current: { provider: current.provider, model: current.model },
      onSelect: async (provider, model) => {
        if (shared) await saveSharedModelReference(plugin, role, provider, model);
        else await saveOperationModelReference(plugin, operation, role, provider, model);
      },
      refreshDisplay
    });
  }
  // Slice C: the reasoning row shows the auto-corrected effective value (and
  // the note) for the provider/model this row actually routes to.
  const reasoningState = field === "reasoningEffort"
    ? reasoningEffortDisplayState(plugin.settings, plugin.generationProviderForModel(current.model), current.model, current.reasoningEffort)
    : null;
  const values = field === "provider"
    ? providerDropdownOptions().map((option) => ({ value: option.value, label: option.label }))
    : field === "reasoningEffort"
      ? reasoningEffortOptionsForModel(current.model, current.reasoningEffort, current.provider, plugin.settings?.providerModelCapabilities)
      : providerCatalogModels(plugin.settings, current.provider).map((value) => ({ value, label: modelDisplayName(value) }));
  const setting = new Setting(containerEl).setName(name).setDesc(reasoningState?.note ? `${desc ? `${desc} ` : ""}${reasoningState.note}` : (desc || ""));
  setting.addDropdown((dropdown) => {
    if (!values.some((option) => option.value === current[field]) && current[field]) dropdown.addOption(current[field], String(current[field]));
    for (const option of values) dropdown.addOption(option.value, option.label);
    dropdown.setValue(reasoningState ? reasoningState.value : current[field]).onChange(async (value) => {
      // Slice C: re-picking any value retries the field once and corrects again
      // only if the endpoint rejects it again.
      if (field === "reasoningEffort") plugin.clearReasoningAutoCorrection(plugin.generationProviderForModel(current.model), current.model);
      if (shared) await saveSharedReferenceField(plugin, role, field, value);
      else await saveOperationReferenceField(plugin, operation, role, field, value);
      if (refreshDisplay) refreshDisplay();
    });
  });
  return setting;
}

function renderSharedReferenceControls(containerEl, plugin, role, refreshDisplay) {
  const title = role === "fallback" ? "Shared fallback" : "Shared primary";
  const reference = stableSharedReference(plugin.settings, role);
  settingsHeading(containerEl, title, role === "fallback" ? "Used after an eligible primary failure." : "Used by every operation unless advanced routing is enabled.");
  referenceDropdownSetting(containerEl, `${title} provider`, "Provider is stored with the model; bare model IDs are never guessed.", plugin, { role, field: "provider", shared: true, refreshDisplay });
  referenceDropdownSetting(containerEl, `${title} model`, "Provider-scoped model catalog; saved selections remain available when a catalog is empty.", plugin, { role, field: "model", shared: true, refreshDisplay });
  referenceDropdownSetting(containerEl, `${title} reasoning`, "Reasoning level for this saved reference.", plugin, { role, field: "reasoningEffort", shared: true, refreshDisplay });
  if (role === "primary") new Setting(containerEl).setName("Configured models").setDesc(`${configuredAiModelSummary(plugin)} Active: ${stableProviderLabel(reference.provider)} / ${modelDisplayName(reference.model)}.`);
}

function renderSharedAiRoutingSettings(containerEl, plugin, refreshDisplay) {
  renderSharedReferenceControls(containerEl, plugin, "primary", refreshDisplay);
  toggleSetting(containerEl, "Enable AI fallback", "Allow one configured fallback attempt after an eligible primary failure.", plugin, "enableAiModelFallback");
  renderSharedReferenceControls(containerEl, plugin, "fallback", refreshDisplay);
  // Slice B: explicit reasoning capability probe. Never automatic; one tiny
  // fixed request pair per configured generation model (no vault content).
  new Setting(containerEl).setName("Check model capabilities").setDesc("Sends one tiny fixed question (\"What is 17*23?\") to the configured generation models to classify reasoning support. No vault content is sent, it never runs automatically, and your reasoning settings are left unchanged.").addButton((button) => {
    button.setButtonText("Check model capabilities").onClick(async () => {
      button.setDisabled(true);
      try {
        const targets = [stableSharedReference(plugin.settings, "primary")];
        if (plugin.settings.enableAiModelFallback) targets.push(stableSharedReference(plugin.settings, "fallback"));
        const seen = new Set();
        const messages = [];
        for (const reference of targets) {
          const model = String(reference.model || "").trim();
          const key = `${reference.provider}:${model.toLowerCase()}`;
          if (!model || seen.has(key)) continue;
          seen.add(key);
          const result = await plugin.probeModelReasoningCapability(model);
          if (result?.message) messages.push(result.message);
        }
        new Notice(messages.length ? messages.join(" ") : "No generation model is configured.");
        if (refreshDisplay) refreshDisplay();
      } catch (error) {
        new Notice(`Capability check failed: ${error.message || error}`);
      } finally {
        button.setDisabled(false);
      }
    });
  });
  toggleSetting(containerEl, "Optimize structured AI use", "Use lower reasoning only for simple scheduler and policy calls.", plugin, "optimizeStructuredAiUsage");
  toggleSetting(containerEl, "Use provider prompt caching", "Cache stable instructions only when the selected provider supports it.", plugin, "enableOpenAiPromptCaching");
  toggleSetting(containerEl, "Prompt caching for Claude models", "When on, requests to models whose name contains \"claude\" mark the repeated part of each task description request so the provider can cache it, which lowers cost and time for the later requests of a note. Turn this off if a model is misidentified as Claude or its endpoint rejects the setting.", plugin, "promptCacheHints", () => clearPromptCacheHintRejection(plugin));
  new Setting(containerEl).setName("Refresh Models").setDesc("Explicitly load provider model catalogs; typing and display-only selection never refreshes.").addButton((button) => button.setButtonText("Refresh Models").onClick(async () => {
    try { await plugin.refreshOpenAIModels(true); if (refreshDisplay) refreshDisplay(); } catch (error) { new Notice(`Could not refresh models: ${error.message || error}`); }
  }));
  new Setting(containerEl).setName("Test Provider").setDesc("Explicitly validate the selected provider connection.").addButton((button) => button.setButtonText("Test Provider").setCta().onClick(async () => {
    try { await plugin.validateAiSetup(true); if (refreshDisplay) refreshDisplay(); } catch (error) { new Notice(`Provider test failed: ${error.message || error}`); }
  }));
}

function renderAdvancedOperationSettings(containerEl, plugin, refreshDisplay) {
  const advanced = settingsDisclosure(containerEl, "Advanced operation routing", "Optional per-operation overrides. When disabled, all eight operations inherit the shared references.", Boolean(plugin.settings.enableMultiProviderOperationModels), "semantic-todoist-operation-disclosure");
  toggleSetting(advanced, "Enable per-operation overrides", "Opt in before changing an operation-specific primary or fallback.", plugin, "enableMultiProviderOperationModels");
  if (plugin.settings.enableMultiProviderOperationModels !== true) return;
  for (const operation of AI_OPERATION_KEYS) {
    const operationBody = settingsDisclosure(advanced, STABLE_OPERATION_LABELS[operation] || operation, "Primary and fallback are resolved from the shared references until explicitly overridden.", false, "semantic-todoist-operation-disclosure");
    renderOperationReferenceControls(operationBody, plugin, operation, "primary", refreshDisplay);
    renderOperationReferenceControls(operationBody, plugin, operation, "fallback", refreshDisplay);
  }
}

function renderOperationReferenceControls(containerEl, plugin, operation, role, refreshDisplay) {
  const label = role === "fallback" ? "Fallback" : "Primary";
  referenceDropdownSetting(containerEl, `${label} provider`, `${label} provider for ${STABLE_OPERATION_LABELS[operation] || operation}.`, plugin, { operation, role, field: "provider", refreshDisplay });
  referenceDropdownSetting(containerEl, `${label} model`, "Provider-scoped model selection.", plugin, { operation, role, field: "model", refreshDisplay });
  referenceDropdownSetting(containerEl, `${label} reasoning`, "Saved reasoning level.", plugin, { operation, role, field: "reasoningEffort", refreshDisplay });
}

function providerEmbeddingSettings(containerEl, plugin, refreshDisplay) {
  const normalized = normalizeStableSettings(plugin.settings);
  let reference = normalized.embeddingModelReference;
  new Setting(containerEl).setName("Embedding provider").setDesc("Indexes are provider/model/dimension specific and are never mixed.").addDropdown((dropdown) => {
    for (const option of providerDropdownOptions(null, true)) dropdown.addOption(option.value, option.label);
    dropdown.setValue(reference.provider).onChange(async (value) => {
      // Route through the canonical identity-change path so cached query/dedup
      // embeddings are cleared and the index for the new identity is loaded from
      // disk (no network indexing); the old in-memory index must not stay usable.
      await plugin.setEmbeddingReference(value, plugin.settings.embeddingModel);
      reference = normalizeStableSettings(plugin.settings).embeddingModelReference;
      if (refreshDisplay) refreshDisplay();
    });
  });
  modelComboboxSetting(containerEl, "Embedding model", "Provider-scoped catalog; changing this control saves state but does not make a network request.", plugin, {
    inputValue: reference.model ? `${stableProviderLabel(reference.provider)}: ${reference.model}` : "",
    groups: modelComboboxGroups(plugin.settings, { embedding: true }),
    allowedProviders: MODEL_COMBOBOX_PROVIDER_ORDER.filter((p) => p !== "anthropic").slice(),
    current: { provider: reference.provider, model: reference.model },
    onSelect: async (provider, model) => {
      // Same canonical path as above: clear stale caches, load the new identity.
      await plugin.setEmbeddingReference(provider, model);
      reference = normalizeStableSettings(plugin.settings).embeddingModelReference;
      if (refreshDisplay) refreshDisplay();
    },
    refreshDisplay
  });
  new Setting(containerEl).setName("Embedding capability").setDesc(embeddingCapabilitySummary(plugin.settings, reference.provider, reference.model));
  new Setting(containerEl).setName("Embedding dimension").setDesc("Use the provider's native dimension when blank; a saved positive value becomes part of index identity.").addText((text) => {
    text.inputEl.type = "number";
    text.inputEl.min = "0";
    text.setValue(String(plugin.settings.embeddingDimension || "")).onChange(async (value) => {
      const parsed = Number.parseInt(value, 10);
      plugin.settings.embeddingDimension = Number.isInteger(parsed) && parsed > 0 ? parsed : 0;
      await plugin.saveSettings();
    });
  });
  new Setting(containerEl).setName("Validate embedding provider").setDesc("Runs one small embedding request with the saved provider and model. It never changes settings, refreshes catalogs, or touches the index.").addButton((button) => {
    button.setButtonText("Validate embedding provider").setCta().onClick(async () => {
      try { await plugin.validateEmbeddingProvider(true); } catch (error) { /* label-only: validateEmbeddingProvider already reports safely */ }
    });
  });
  new Setting(containerEl).setName("Warm embedding server on startup").setDesc(settingDescription("Warm embedding server on startup", "warmEmbeddingServerOnStartup")).addToggle((toggle) => {
    toggle.setValue(plugin.settings.warmEmbeddingServerOnStartup === true).onChange(async (value) => {
      plugin.settings.warmEmbeddingServerOnStartup = value === true;
      if (value === true) plugin.semanticEmbeddingWarmupAttemptedFor = "";
      await plugin.saveSettings();
    });
  });
}

function embeddingCapabilitySummary(settings, provider, model) {
  const catalog = settings.providerEmbeddingModels?.[stableSupportedProvider(provider)] || [];
  const listed = Array.isArray(catalog) && catalog.some((value) => String(value) === String(model));
  return listed ? "Provider catalog reports this model as embedding-capable." : "Capability is not reported locally; the explicit provider test is required before rebuilding.";
}

// Search model groups for the web-research row: modelComboboxGroups only walks
// its fixed provider order, so the web-search-only anthropic group is composed
// here from the provider default plus whatever catalog the provider fills in.
function webSearchModelComboboxGroups(settings, providers) {
  const groups = modelComboboxGroups(settings, { providers });
  if (!Array.isArray(providers) || !providers.includes("anthropic")) return groups;
  const catalog = Array.isArray(settings?.providerGenerationModels?.anthropic) ? settings.providerGenerationModels.anthropic : [];
  const models = uniqueValues([WEB_SEARCH_PROVIDER_DEFAULT_MODELS.anthropic, ...catalog.map((value) => String(value || "").trim()).filter(Boolean)]);
  const existing = groups.find((group) => group.provider === "anthropic");
  if (existing) existing.models = uniqueValues([...models, ...existing.models]);
  else groups.push({ provider: "anthropic", label: "Anthropic", models });
  return groups;
}

function webResearchSettings(containerEl, plugin) {
  const providers = ["openai", "gemini", "openrouter", "anthropic"];
  const provider = normalizeWebSearchProvider(plugin.settings.chatWebSearchProvider);
  dropdownSettingWithDesc(containerEl, "Search provider", "Native search is available for OpenAI, Gemini, OpenRouter, and Anthropic.", plugin, "chatWebSearchProvider", providers);
  modelComboboxSetting(containerEl, "Search model", "Provider-scoped model used only by an explicit search mode.", plugin, {
    inputValue: plugin.settings.chatWebSearchModel
      ? `${stableProviderLabel(provider)}: ${plugin.settings.chatWebSearchModel}`
      : "Provider default",
    groups: webSearchModelComboboxGroups(plugin.settings, providers),
    allowedProviders: providers.slice(),
    includeDefault: true,
    defaultProvider: provider,
    current: { provider, model: plugin.settings.chatWebSearchModel || "" },
    onSelect: async (selectedProvider, selectedModel) => {
      plugin.settings.chatWebSearchProvider = normalizeWebSearchProvider(selectedProvider);
      plugin.settings.chatWebSearchModel = String(selectedModel || "");
      await plugin.saveSettings();
    }
  });
  toggleSetting(containerEl, "Save Research notes", "Save a sanitized Research note only after citation validation succeeds.", plugin, "chatWebSaveResearch");
}

function reasoningEffortSetting(containerEl, name, desc, plugin, key, model) {
  const current = normalizeReasoningEffort(plugin.settings[key], DEFAULT_SETTINGS[key]);
  const provider = usesGeminiChatModel(model) ? "gemini" : stableSupportedProvider(plugin.settings.aiModelProvider, "");
  const options = reasoningEffortOptionsForModel(model, current, provider, plugin.settings?.providerModelCapabilities);
  const modelName = modelDisplayName(model);
  const reasoningState = reasoningEffortDisplayState(plugin.settings, provider, model, current);
  const providerNote = usesOpenAIChatModel(model)
    ? "OpenAI reasoning models use the Responses API reasoning.effort field."
    : isGemini3ReasoningModel(model)
      ? "Gemini 3 models use the provider's thinkingLevel field."
      : "This model has no compatible level control here, so Provider default is used.";
  new Setting(containerEl)
    .setName(name)
    .setDesc(`${desc} Active model: ${modelName}. ${providerNote}${reasoningState.note ? ` ${reasoningState.note}` : ""}`)
    .addDropdown((dropdown) => {
      for (const option of options) dropdown.addOption(option.value, option.label);
      dropdown.setValue(reasoningState.value).onChange(async (value) => {
        // Slice C: re-picking any value clears the correction for this model so
        // the next request tries the chosen value once again.
        plugin.clearReasoningAutoCorrection(provider, model);
        plugin.settings[key] = normalizeReasoningEffort(value);
        await plugin.saveSettings();
      });
    });
}

function taskGenerationPromptTemplateSetting(containerEl, plugin) {
  const current = plugin.settings.taskGenerationPromptTemplate || DEFAULT_SETTINGS.taskGenerationPromptTemplate;
  new Setting(containerEl)
    .setName("Task generation prompt")
    .setDesc("Default task-generation prompt used by the Create Todoist tasks command. Prompt templates with createTasks enabled use their own prompt text directly.")
    .addDropdown((dropdown) => {
      dropdown.addOption(current, current);
      dropdown.setValue(current);
      dropdown.onChange(async (value) => {
        plugin.settings.taskGenerationPromptTemplate = value;
        await plugin.saveSettings();
      });
      plugin.getPromptTemplates().then((templates) => {
        const candidates = templates.filter((template) => isTaskGenerationTemplate(template));
        if (dropdown.selectEl) dropdown.selectEl.empty();
        const values = new Set();
        for (const template of candidates) {
          const value = template.source || template.name;
          if (!value || values.has(value)) continue;
          values.add(value);
          dropdown.addOption(value, template.name || value);
        }
        if (!values.has(current)) dropdown.addOption(current, current);
        dropdown.setValue(values.has(current) ? current : (candidates[0]?.source || candidates[0]?.name || current));
      }).catch((error) => {
        console.error("Could not load task generation templates", error);
      });
    });
}

function taskGenerationPromptProfileSettings(containerEl, plugin) {
  new Setting(containerEl)
    .setName("Task-generation prompt profile mode")
    .setDesc(settingDescription("Task-generation prompt profile mode", "taskGenerationPromptProfileMode", "Auto follows the exact configured primary model when it is GPT 5.6 Luna or GPT 5.6 Terra; Manual uses the saved profile below."))
    .addDropdown((dropdown) => {
      dropdown.addOption("auto", "Auto");
      dropdown.addOption("manual", "Manual");
      dropdown.setValue(normalizeTaskGenerationPromptProfileMode(plugin.settings.taskGenerationPromptProfileMode)).onChange(async (value) => {
        plugin.settings.taskGenerationPromptProfileMode = normalizeTaskGenerationPromptProfileMode(value);
        await plugin.saveSettings();
      });
    });
  new Setting(containerEl)
    .setName("Task-generation prompt profile")
    .setDesc(settingDescription("Task-generation prompt profile", "taskGenerationPromptProfile", "Choose the bounded task and description guidance used when prompt profile mode is Manual."))
    .addDropdown((dropdown) => {
      for (const profile of TASK_GENERATION_PROMPT_PROFILES) dropdown.addOption(profile, TASK_GENERATION_PROMPT_PROFILE_NAMES[profile]);
      dropdown.setValue(normalizeTaskGenerationPromptProfile(plugin.settings.taskGenerationPromptProfile)).onChange(async (value) => {
        plugin.settings.taskGenerationPromptProfile = normalizeTaskGenerationPromptProfile(value);
        await plugin.saveSettings();
      });
    });
}

function todoistProjectSetting(containerEl, plugin, refreshDisplay) {
  const projects = plugin.settings.availableTodoistProjects || [];
  const currentId = plugin.settings.todoistTaskProjectId || plugin.settings.todoistInboxProjectId || "";
  const currentName = plugin.settings.todoistTaskProjectName || "Inbox";
  const desc = projects.length
    ? `New email and note tasks are created in this Todoist project. Projects loaded: ${projects.length}. Last refreshed: ${plugin.settings.todoistProjectsFetchedAt || "unknown"}.`
    : "Defaults to Todoist Inbox. Refresh after adding your Todoist token to choose another project.";
  const setting = new Setting(containerEl).setName("Todoist task project").setDesc(desc)
    .addDropdown((dropdown) => {
      if (currentId && !projects.some((project) => project.id === currentId)) dropdown.addOption(currentId, currentName);
      if (!projects.length && !currentId) dropdown.addOption("", "Inbox");
      for (const project of projects) dropdown.addOption(project.id, project.isInbox ? `${project.name} (Inbox)` : project.name);
      dropdown.setValue(currentId || "");
      dropdown.onChange(async (value) => {
        const selected = projects.find((project) => project.id === value);
        plugin.settings.todoistTaskProjectId = value;
        plugin.settings.todoistTaskProjectName = selected?.name || currentName || "Inbox";
        await plugin.saveSettings();
      });
    })
    .addButton((button) => button.setButtonText("Refresh").onClick(async () => {
      try {
        await plugin.refreshTodoistProjects(true);
        if (refreshDisplay) refreshDisplay();
      } catch (error) {
        new Notice(`Could not load Todoist projects: ${error.message || error}`);
      }
    }));
  setting.settingEl.addClass("semantic-todoist-project-setting");
}

