    snapshotOnlyCount: 0,
    incompleteLocalReferenceCount: 0,
    sourceRecordCount: 0,
    unverifiedSourceRecordCount: 0,
    ambiguousSourceRecordCount: 0,
    unverifiedLocalRecordCount: 0,
    topLevelUnverifiedRecordCount: 0,
