function sectionKey(name) { return singleLine(name).toLowerCase(); }

async function appendMarkdownBlock(app, file, markdown) {
  if (!(file instanceof TFile)) throw new Error("Active note was not found.");
  const current = await app.vault.read(file);
  await app.vault.modify(file, markdownWithSingleBlankLineBeforeAppend(current, markdown));
}

function markdownWithSingleBlankLineBeforeAppend(current, markdown) {
  const before = String(current || "").replace(/\s+$/, "");
  const block = String(markdown || "").trim();
  return before ? `${before}\n\n${block}\n` : `${block}\n`;
}

async function ensureVaultFolder(app, folderPath) {
  const parts = trimSlashes(folderPath).split("/").filter(Boolean);
  let current = "";
  for (const part of parts) {
    current = current ? `${current}/${part}` : part;
    if (!app.vault.getAbstractFileByPath(current)) {
      try {
        await app.vault.createFolder(current);
      } catch (error) {
        if (!/exist/i.test(error.message || String(error))) throw error;
      }
    }
  }
}

function normalizeTodoistProjects(projects) {
  return (projects || [])
    .map((project) => ({
      id: String(project.id || ""),
      name: singleLine(project.name || "Untitled project"),
      isInbox: Boolean(project.isInbox || project.is_inbox_project || project.inbox_project)
    }))
    .filter((project) => project.id)
    .sort((a, b) => (a.isInbox === b.isInbox ? a.name.localeCompare(b.name) : a.isInbox ? -1 : 1));
}

function normalizeTodoistSections(sections, projectId) {
  return (sections || [])
    .map((section) => ({
      id: String(section.id || ""),
      name: singleLine(section.name || ""),
      projectId: String(section.project_id || section.projectId || projectId || "")
    }))
    .filter((section) => section.id && section.name)
    .sort((a, b) => a.name.localeCompare(b.name));
}

function normalizeCompletedTodoistReferencePage(json) {
  if (!json || typeof json !== "object" || Array.isArray(json)) throw new Error("Todoist completed tasks returned a malformed page: expected an object with an items array");
  if (!Array.isArray(json.items)) throw new Error("Todoist completed tasks returned a malformed page: items is not an array");
  const tasks = json.items
    .map(normalizeTodoistTask)
    .map((task) => Object.assign({}, task, { isCompleted: true }))
    .filter((task) => task.id && task.content);
  const projects = normalizeTodoistProjects(json.projects || []);
  const sections = normalizeTodoistSections(json.sections || [], "");
  const fingerprint = json.items
    .map((item) => String(item?.id || ""))
    .filter(Boolean)
    .sort()
    .join("\n");
  return { tasks, projects, sections, size: json.items.length, fingerprint };
}

function normalizeTodoistTask(task) {
  return {
    id: String(task.id || ""),
    content: singleLine(task.content || ""),
    description: task.description || "",
    parentId: String(task.parent_id || task.parentId || ""),
    sectionId: String(task.section_id || task.sectionId || ""),
    projectId: String(task.project_id || task.projectId || ""),
    labels: (task.labels || []).map(cleanLabel).filter(Boolean),
    priority: normalizePriority(task.priority),
    dueDate: task.due?.date || task.due_date || "",
    deadlineDate: task.deadline?.date || task.deadline_date || "",
    duration: normalizeTodoistDuration(task.duration),
    isCompleted: Boolean(task.is_completed || task.checked || task.completed)
  };
}

function findExistingTodoistTaskMatch(parsed, existingTasks, parentId = "") {
  const content = singleLine(parsed.content || "").toLowerCase();
  if (!content) return null;
  const due = parsed.due_date || "";
  const deadline = parsed.deadline_date || "";
  const projectName = singleLine(parsed.projectName || "").toLowerCase();
  const candidates = existingTasks.filter((task) => {
    if (singleLine(task.content).toLowerCase() !== content) return false;
    if (parentId && task.parentId && task.parentId !== parentId) return false;
    if (parsed.isSubtask && parentId && task.parentId !== parentId) return false;
    if (projectName && task.projectName && singleLine(task.projectName).toLowerCase() !== projectName) return false;
    if (due && task.dueDate && datePart(task.dueDate) !== due) return false;
    if (deadline && task.deadlineDate && task.deadlineDate !== deadline) return false;
    return true;
  });
  candidates.sort((a, b) => existingTodoistTaskMatchScore(b, parsed, parentId) - existingTodoistTaskMatchScore(a, parsed, parentId));
  return candidates[0] || null;
}

function existingTodoistTaskMatchScore(task, parsed, parentId) {
  let score = 0;
  if (parsed.isSubtask && parentId && task.parentId === parentId) score += 5;
  if (parsed.projectName && task.projectName && singleLine(parsed.projectName).toLowerCase() === singleLine(task.projectName).toLowerCase()) score += 5;
  if (parsed.section && task.section && singleLine(parsed.section).toLowerCase() === singleLine(task.section).toLowerCase()) score += 4;
  if (!parsed.isSubtask && parsed.section && task.sectionId) score += 4;
  if (!parsed.isSubtask && !task.parentId) score += 2;
  if (parsed.due_date && datePart(task.dueDate) === parsed.due_date) score += 1;
  if (parsed.deadline_date && task.deadlineDate === parsed.deadline_date) score += 1;
  return score;
}

function countCreatedTaskTree(stats = emptyTaskDeduplicationStats(), task = {}) {
  stats.created += 1;
  for (const subtask of task.subtasks || []) stats.created += 1;
  return stats;
}

function emptyTaskDeduplicationStats() {
  return {
    checked: 0,
    merged: 0,
    created: 0,
    ambiguous: 0,
    copiedSubtasks: 0,
    removedSubtasks: 0,
    generatedDuplicates: 0,
    localConfirmed: 0,
    aiUsed: 0,
    taskGenerationUsed: 0,
    semanticTelemetry: {
      candidateCount: 0,
      embeddingCacheHits: 0,
      embeddingCalls: 0,
      providerCalls: 0,
      providerCost: 0,
      elapsedMs: 0,
      degraded: false,
      degradedReason: "",
      escalation: false
    },
    degradedState: "legacy",
    degradedReason: "",
    candidateOutcomes: [],
    candidateFlags: [],
    matches: []
  };
}

function taskDeduplicationRunSummary(stats = emptyTaskDeduplicationStats()) {
  return `${stats.merged || 0} linked to existing tasks, ${stats.created || 0} left as new, ${stats.ambiguous || 0} ambiguous, ${stats.localConfirmed || 0} confirmed locally, ${stats.aiUsed || 0} sent to AI as a last resort, ${stats.copiedSubtasks || 0} existing subtasks copied, ${stats.generatedDuplicates || 0} generated duplicates collapsed, ${stats.taskGenerationUsed || 0} confirmed duplicate updates regenerated, ${(stats.candidateFlags || []).length} local-only duplicate candidates flagged.`;
}

function shouldUseLiveTodoistDeduplicationCandidates(options = {}) {
  if (options.includeLiveTodoistCandidates === false) return false;
  if (options.includeLiveTodoistCandidates === true) return true;
  return /^(email|note|notes|task generation|task-generation)$/i.test(String(options.source || ""));
}

function liveTodoistTaskDeduplicationCandidates(tasks = [], settings = DEFAULT_SETTINGS) {
  const byId = new Map((tasks || []).map((task) => [String(task.id || ""), task]).filter(([id]) => id));
  const childTextByParentId = new Map();
  for (const task of tasks || []) {
    const parentId = String(task.parentId || "");
    if (!parentId) continue;
    const text = [task.content, task.description].filter(Boolean).join(" ");
    if (!text) continue;
    childTextByParentId.set(parentId, [childTextByParentId.get(parentId) || "", text].filter(Boolean).join(" "));
  }
  return (tasks || [])
    .filter((task) => task?.id && task.content && !task.isCompleted)
    .map((task) => {
      const parentId = String(task.parentId || "");
      const parent = parentId ? byId.get(parentId) || {} : {};
      const childText = childTextByParentId.get(String(task.id || "")) || "";
      const siblingText = parentId ? childTextByParentId.get(parentId) || "" : "";
      const normalized = {
        id: String(task.id || ""),
        oid: task.oid || "",
        content: task.content || "",
        description: task.description || "",
        labels: (task.labels || []).map(cleanLabel).filter(Boolean),
        priority: normalizePriority(task.priority || 1),
        due_date: datePart(task.due_date || task.dueDate || ""),
        deadline_date: task.deadline_date || task.deadlineDate || "",
        duration: normalizeTodoistDuration(task.duration),
        isCompleted: false,
        isSubtask: Boolean(parentId),
        parentId,
        parentContent: parent.content || task.parentContent || "",
        parentDescription: parent.description || task.parentDescription || "",
        section: task.section || "",
        sectionId: task.sectionId || "",
        projectId: task.projectId || "",
        projectName: task.projectName || "",
        childText,
        siblingText,
        parentChildText: siblingText
      };
      normalized.knowledge = taskKnowledgeSnapshot(normalized, settings, childText, task.knowledge || null);
      return { id: normalized.id, task: normalized };
    });
}

async function deduplicateGeneratedTaskBatch(tasks = [], settings = DEFAULT_SETTINGS, options = {}, aiDecisionFn = null, taskGenerationFn = null) {
  const stats = { merged: 0, matches: [], localConfirmed: 0, aiUsed: 0, taskGenerationUsed: 0, ambiguous: 0, candidateFlags: [] };
  if (!Array.isArray(tasks) || tasks.length < 2) return stats;
  for (let i = 0; i < tasks.length; i += 1) {
    const task = tasks[i];
    if (!task || task.id || task.isSubtask) continue;
    const candidates = generatedTaskBatchCandidates(tasks, i);
    const decision = bestTaskDeduplicationMatch(task, candidates, settings, Object.assign({}, options, { isSubtask: false, intraBatch: true }));
    if (!decision.candidate?.generatedTask) continue;
    if (!isAiMediatedTaskDeduplicationCandidate(decision)) continue;
    const resolutionOptions = Object.assign({}, options, { intraBatch: true });
    const resolution = taskDeduplicationResolution(decision, settings, resolutionOptions);
    if (resolution === "none") {
      if (decision.candidate && (decision.outcome === "ambiguous-ai" || decision.decision === "ambiguous")) {
        flagPossibleDuplicateTask(stats, task, decision, settings, resolutionOptions);
      }
      continue;
    }
    if (resolution === "manual") {
      flagPossibleDuplicateTask(stats, task, decision, settings, resolutionOptions);
      continue;
    }
    if (resolution === "local") {
      stats.localConfirmed += 1;
    } else {
      const aiDecision = typeof aiDecisionFn === "function" ? await aiDecisionFn(task, decision, resolutionOptions) : null;
      if (aiDecision?.used) stats.aiUsed += 1;
      if (aiDecision?.match !== true) {
        if (aiDecision?.used) flagPossibleDuplicateTask(stats, task, decision, settings, resolutionOptions);
        continue;
      }
    }
    const generatedUpdate = options.semanticDedupeState?.enabled
      ? { used: false, task }
      : (typeof taskGenerationFn === "function" ? await taskGenerationFn(task, decision, resolutionOptions) : null);
    if (!generatedUpdate?.task) {
      flagPossibleDuplicateTask(stats, task, decision, settings, resolutionOptions);
      continue;
    }
    const target = decision.candidate.generatedTask;
    if (generatedUpdate.used) {
      stats.taskGenerationUsed += 1;
      applyTaskGenerationDuplicateUpdate(target, generatedUpdate.task, settings);
    } else {
      mergeConfirmedGeneratedTaskTree(target, task, settings);
    }
    markGeneratedDuplicateTask(target, decision, settings);
    stats.merged += 1;
    stats.matches.push(taskDeduplicationMatchSummary(task, Object.assign({}, decision, {
      id: "",
      reasons: uniqueValues(["merged with generated task"].concat(decision.reasons || []))
    })));
    tasks.splice(i, 1);
    i -= 1;
  }
  return stats;
}

function mergeConfirmedGeneratedTaskTree(target = {}, duplicate = {}, settings = DEFAULT_SETTINGS) {
  if (!target || !duplicate) return target;
  if ((!target.description || target.description.length < (duplicate.description || "").length) && duplicate.description) target.description = duplicate.description;
  target.due_date = target.due_date || duplicate.due_date || "";
  target.deadline_date = target.deadline_date || duplicate.deadline_date || "";
  target.priority = normalizePriority(target.priority || duplicate.priority || 1);
  target.labels = mergedTaskLabelsForDeduplication(target.labels || [], duplicate.labels || [], settings);
  const existingByIdentity = new Map();
  for (const subtask of target.subtasks || []) {
    const key = JSON.stringify(semanticDedupeStructuredIdentity(subtask));
    if (key !== "{}" && !existingByIdentity.has(key)) existingByIdentity.set(key, subtask);
  }
  for (const sourceSubtask of duplicate.subtasks || []) {
    const key = JSON.stringify(semanticDedupeStructuredIdentity(sourceSubtask));
    const existing = key !== "{}" ? existingByIdentity.get(key) : null;
    if (existing) {
      existing.description = existing.description || sourceSubtask.description || "";
      existing.due_date = existing.due_date || sourceSubtask.due_date || "";
      existing.deadline_date = existing.deadline_date || sourceSubtask.deadline_date || "";
      existing.labels = mergedTaskLabelsForDeduplication(existing.labels || [], sourceSubtask.labels || [], settings);
      continue;
    }
    const next = Object.assign({}, sourceSubtask, {
      oid: sourceSubtask.oid || generateUniqueOid(settings),
      isSubtask: true,
      parentId: target.id || sourceSubtask.parentId || "",
      parentOid: target.oid || sourceSubtask.parentOid || "",
      parentContent: target.content || sourceSubtask.parentContent || ""
    });
    target.subtasks = target.subtasks || [];
    target.subtasks.push(next);
    if (key !== "{}") existingByIdentity.set(key, next);
  }
  target.knowledge = taskKnowledgeSnapshot(target, settings, taskDeduplicationSubtaskText(target), target.knowledge || null);
  target.descriptionShouldSync = true;
  return target;
}

function generatedTaskBatchCandidates(tasks = [], beforeIndex = 0) {
  const candidates = [];
  for (let index = 0; index < beforeIndex; index += 1) {
    const task = tasks[index];
    if (!task || task.isSubtask) continue;
    candidates.push({
      id: task.id || task.oid || `generated:${index}`,
      generatedTask: task,
      task: Object.assign({}, task, {
        id: task.id || task.oid || `generated:${index}`,
        childText: taskDeduplicationSubtaskText(task)
      })
    });
  }
  return candidates;
}

function duplicatePairNeedsTaskGeneration(incoming = {}, existing = {}, options = {}) {
  if (options.intraBatch === true) return true;
  if (options.isSubtask === true) return false;
  if (existing.due_date && !incoming.due_date) return true;
  if (existing.deadline_date && !incoming.deadline_date) return true;
  if (isRichTodoistDescription(existing.description) && !isRichTodoistDescription(incoming.description)) return true;
  const incomingLinks = new Set(extractDescriptionLinkRecords(incoming.description || "", DEFAULT_SETTINGS).map((link) => link.url));
  return extractDescriptionLinkRecords(existing.description || "", DEFAULT_SETTINGS).some((link) => !incomingLinks.has(link.url));
}

function duplicateTaskGenerationPreservesEvidence(generated = {}, incoming = {}, existing = {}, settings = DEFAULT_SETTINGS) {
  if (!generated?.content) return false;
  if (mainTaskClarityReason(generated) !== "passed") return false;
  if ((isRichTodoistDescription(incoming.description) || isRichTodoistDescription(existing.description)) && !isUsefulDescriptionSummary(generated.description, generated.content, settings)) return false;
  const sourceDueDates = uniqueValues([incoming.due_date, existing.due_date].filter(Boolean));
  if (sourceDueDates.length && !generated.due_date) return false;
  const sourceDeadlines = uniqueValues([incoming.deadline_date, existing.deadline_date].filter(Boolean));
  if (sourceDeadlines.length && !generated.deadline_date) return false;
  const generatedLinks = new Set(extractDescriptionLinkRecords(generated.description || "", settings).map((link) => link.url));
  const sourceLinks = uniqueValues([incoming.description, existing.description]
    .flatMap((description) => extractDescriptionLinkRecords(description || "", settings).map((link) => link.url)));
  if (sourceLinks.some((link) => !generatedLinks.has(link))) return false;
  return true;
}

function stableTaskTreeIdentity(task = {}) {
  const stableId = String(task.todoistId || task.id || task.oid || "").trim();
  if (stableId) return `id:${stableId.toUpperCase()}`;
  const structured = semanticDedupeStructuredIdentity(task);
  return Object.keys(structured).length ? `structured:${JSON.stringify(structured)}` : "";
}

function applyTaskGenerationDuplicateUpdate(target = {}, generated = {}, settings = DEFAULT_SETTINGS) {
  const previousSubtasks = target.subtasks || [];
  target.content = singleLine(generated.content || target.content || "");
  target.description = generated.description || target.description || "";
  target.due_date = generated.due_date || target.due_date || "";
  target.deadline_date = generated.deadline_date || target.deadline_date || "";
  target.priority = normalizePriority(generated.priority || target.priority || 1);
  target.labels = mergedTaskLabelsForDeduplication(generated.labels || [], target.labels || [], settings);
  if (!target.isSubtask) {
    const mergedSubtasks = [];
    const seenSubtaskIdentities = new Set();
    for (const subtask of [...previousSubtasks, ...(generated.subtasks || [])]) {
      const identity = stableTaskTreeIdentity(subtask);
      if (identity && seenSubtaskIdentities.has(identity)) continue;
      if (identity) seenSubtaskIdentities.add(identity);
      const previous = identity ? previousSubtasks.find((candidate) => stableTaskTreeIdentity(candidate) === identity) || {} : {};
      const next = Object.assign({}, previous, subtask);
      for (const field of TASK_SUBTASK_STABLE_IDENTITY_FIELDS) {
        if (Object.prototype.hasOwnProperty.call(previous, field) && previous[field] !== undefined) next[field] = previous[field];
      }
      Object.assign(next, {
        oid: previous.oid || subtask.oid || generateUniqueOid(settings),
        isSubtask: true,
        parentId: target.id || previous.parentId || "",
        parentOid: target.oid || previous.parentOid || "",
        parentContent: target.content || "",
        projectId: target.projectId || previous.projectId || "",
        projectName: target.projectName || previous.projectName || "",
        section: target.section || previous.section || "",
        sectionId: target.sectionId || previous.sectionId || ""
      });
      next.knowledge = taskKnowledgeSnapshot(next, settings, "", previous.knowledge || null);
      mergedSubtasks.push(next);
    }
    target.subtasks = mergedSubtasks;
  }
  target.knowledge = taskKnowledgeSnapshot(target, settings, taskDeduplicationSubtaskText(target), target.knowledge || null);
  target.descriptionShouldSync = true;
  return target;
}

function markGeneratedDuplicateTask(target, decision = {}, settings = DEFAULT_SETTINGS) {
  if (!target) return target;
  target.knowledge = taskKnowledgeSnapshot(target, settings, taskDeduplicationSubtaskText(target), target.knowledge || null);
  target.descriptionShouldSync = true;
  target.deduplication = {
    todoistId: target.id || "",
    confidence: decision.confidence || 0,
    reasons: uniqueValues(["merged with generated task"].concat(decision.reasons || []))
  };
  return target;
}

function taskDeduplicationThreshold(settings = DEFAULT_SETTINGS) {
  const strictness = settings.taskDeduplicationStrictness || "conservative";
  if (strictness === "strict") return 90;
  if (strictness === "permissive") return 78;
  return 84;
}

function isAiMediatedTaskDeduplicationCandidate(decision = {}) {
  return Boolean(decision?.candidate && (decision.decision === "merge" || decision.decision === "ambiguous" || decision.outcome === "merge" || decision.outcome === "ambiguous-ai"));
}

function taskDeduplicationResolution(decision = {}, settings = DEFAULT_SETTINGS, options = {}) {
  if (!isAiMediatedTaskDeduplicationCandidate(decision)) return "none";
  if (decision.hardConflict) return "none";
  if (decision.outcome === "merge" && decision.decision === "merge") return "local";
  if (decision.outcome === "ambiguous-ai") return settings.enableAiAmbiguousTaskDeduplication === true ? "ai" : "none";
  if (decision.decision === "ambiguous") return isCredibleLocalAmbiguousTaskCandidate(decision, settings, options) ? "manual" : "none";
  if (settings.enableAiAmbiguousTaskDeduplication !== true) return "local";
  return isLocallyConclusiveTaskDuplicate(decision, settings, options) ? "local" : "ai";
}

function isCredibleLocalAmbiguousTaskCandidate(decision = {}, settings = DEFAULT_SETTINGS, options = {}) {
  if (decision.decision !== "ambiguous" || decision.hardMismatch || !decision.candidate?.task) return false;
  if (isTaskDeduplicationRoutingBoilerplate(decision.sourceTask) || isTaskDeduplicationRoutingBoilerplate(decision.candidate.task)) return false;
  const strictness = settings.taskDeduplicationStrictness || DEFAULT_SETTINGS.taskDeduplicationStrictness;
  const band = strictness === "strict" ? 6 : strictness === "permissive" ? 14 : 10;
  const confidenceFloor = taskDeduplicationThreshold(settings) - band;
  const confidence = Number(decision.confidence || 0);
  const titleOverlap = Number(decision.titleOverlap || 0);
  const contextOverlap = Number(decision.contextOverlap || 0);
  if (contextOverlap >= 0.55) return true;
  if (confidence >= confidenceFloor && (titleOverlap >= 0.3 || contextOverlap >= 0.38 || decision.projectContextMatch === true)) return true;
  return Boolean(options.intraBatch && decision.batchContextMatch === true && titleOverlap >= 0.2 && contextOverlap >= 0.3);
}

function isTaskDeduplicationRoutingBoilerplate(task = {}) {
  const text = `${task?.content || ""} ${task?.description || ""}`;
  return /\blive[-_\s]?reply[-_\s]?to\b|\breply[-_\s]?to\s+(?:address|alias|mailbox)\b.*\b(?:captur|track|ticket|cop(?:y|ied))\w*/i.test(text);
}

function isLocallyConclusiveTaskDuplicate(decision = {}, settings = DEFAULT_SETTINGS, options = {}) {
  // Local certainty may only come from the semantic decision path or exact
  // stable workflow identity; title similarity/equality is never evidence.
  if (decision.outcome !== "merge" || decision.decision !== "merge" || decision.hardConflict || decision.hardMismatch || !decision.candidate?.task) return false;
  const exactIdentity = (decision.basis || decision.reasons || []).some((reason) => /exact (?:task )?identity|stable (?:todoist )?(?:id|oid)|workflow identity/i.test(String(reason)));
  const semanticScore = Number(decision.semanticScore);
  return exactIdentity || (Number.isFinite(semanticScore) && semanticScore >= 0.88);
}

function semanticDedupeList(value = []) {
  if (Array.isArray(value)) return uniqueValues(value.map((item) => singleLine(item)).filter(Boolean)).sort();
  if (value === undefined || value === null || value === "") return [];
  return [singleLine(value)].filter(Boolean);
}

function semanticDedupeStructuredIdentity(task = {}) {
  const explicit = task.structuredIdentity || task.structured_identity || {};
  const knowledge = task.knowledge || {};
  const identity = {
    action: singleLine(explicit.action || task.action || knowledge.action || ""),
    outcome: singleLine(explicit.outcome || explicit.outcomeType || task.outcome || knowledge.outcome || knowledge.outcomeType || ""),
    deliverable: singleLine(explicit.deliverable || task.deliverable || knowledge.deliverable || ""),
    component: singleLine(explicit.component || task.component || knowledge.component || ""),
    owner: singleLine(explicit.owner || task.owner || knowledge.owner || ""),
    recipient: singleLine(explicit.recipient || task.recipient || knowledge.recipient || ""),
    reviewer: singleLine(explicit.reviewer || task.reviewer || knowledge.reviewer || ""),
    people: semanticDedupeList(explicit.people || task.people || knowledge.people),
    projectId: String(explicit.projectId || task.projectId || ""),
    projectName: singleLine(explicit.projectName || task.projectName || ""),
    sectionId: String(explicit.sectionId || task.sectionId || ""),
    section: singleLine(explicit.section || task.section || ""),
    labels: semanticDedupeList(explicit.labels || task.labels),
    dueDate: String(explicit.dueDate || explicit.due_date || task.due_date || ""),
    deadlineDate: String(explicit.deadlineDate || explicit.deadline_date || task.deadline_date || ""),
    progress: singleLine(explicit.progress || explicit.currentState || task.progress || task.currentState || knowledge.progress || "")
  };
  return Object.fromEntries(Object.entries(identity).filter(([, value]) => Array.isArray(value) ? value.length : value));
}

function semanticDedupeRelationship(task = {}, options = {}) {
  const relationship = task.relationship || task.relation || {};
  return {
    kind: singleLine(relationship.kind || (task.isSubtask || task.parentId || task.parentOid ? "subtask" : "root")),
    isSubtask: Boolean(relationship.isSubtask ?? (task.isSubtask || task.parentId || task.parentOid || options.isSubtask)),
    parentId: String(relationship.parentId || task.parentId || options.parentId || ""),
    parentOid: String(relationship.parentOid || task.parentOid || options.parentOid || ""),
    parentContent: singleLine(relationship.parentContent || task.parentContent || options.parentContent || ""),
    rootId: String(relationship.rootId || task.rootId || task.rootTaskId || ""),
    rootOid: String(relationship.rootOid || task.rootOid || ""),
    childIds: semanticDedupeList(relationship.childIds || task.childTaskIds || (task.subtasks || []).map((item) => item?.id || item?.todoistId)),
    childOids: semanticDedupeList(relationship.childOids || task.childOids || (task.subtasks || []).map((item) => item?.oid)),
    treeDepth: Number(relationship.treeDepth ?? task.treeDepth ?? 0),
    treePath: semanticDedupeList(relationship.treePath || task.treePath)
  };
}

function semanticDedupeCurrentState(task = {}) {
  const state = task.currentState || task.current_state || task.state || task.progress || task.knowledge?.progress || "";
  return task.isCompleted ? "completed" : singleLine(state || "open");
}

function semanticTaskDedupeProgressConflict(left = "", right = "") {
  const a = singleLine(left).toLowerCase();
  const b = singleLine(right).toLowerCase();
  if (!a || !b || a === b) return false;
  if (/\b(?:completed|complete|historical|prior|archived|obsolete|cancelled)\b/.test(a) || /\b(?:completed|complete|historical|prior|archived|obsolete|cancelled)\b/.test(b)) return true;
  const generic = new Set(["open", "pending", "pending-confirmation", "ready-to-send", "current-review", "in-progress", "active"]);
  return !(generic.has(a) && generic.has(b));
}

function taskTreeRepresentation(task = {}, options = {}) {
  const subtasks = Array.isArray(task.subtasks) ? task.subtasks : [];
  const evidenceIds = semanticDedupeList(task.evidence_ids || task.evidenceIds || task.evidence_id || task.evidence?.ids);
  const factRefs = semanticDedupeList(task.fact_refs || task.factRefs || task.fact_refs_ids || task.facts);
  return {
    title: singleLine(task.content || task.title || ""),
    description: singleLine(task.description || ""),
    subtasks: subtasks.map((subtask) => taskTreeRepresentation(subtask, Object.assign({}, options, {
      isSubtask: true,
      parentId: task.id || options.parentId,
      parentOid: task.oid || options.parentOid,
      parentContent: task.content || options.parentContent
    }))),
    structuredIdentity: semanticDedupeStructuredIdentity(task),
    relationship: semanticDedupeRelationship(task, options),
    currentState: semanticDedupeCurrentState(task),
    evidence_ids: evidenceIds,
    fact_refs: factRefs,
    sourceId: String(task.sourceId || task.source_id || ""),
    taskId: String(task.id || task.todoistId || task.oid || ""),
    oid: String(task.oid || "")
  };
}

function taskTreeFingerprint(task = {}, options = {}) {
  const representation = taskTreeRepresentation(task, options);
  return taskWorkflowHash({
    representation,
    provider: String(options.provider || options.embeddingProvider || ""),
    model: String(options.model || options.embeddingModel || ""),
    dimension: Number(options.dimension || options.embeddingDimension || 0),
    indexRevision: Number(options.indexRevision || 0)
  });
}

function semanticTaskDedupeChunkIdentity(chunk = {}) {
  const task = chunk.taskReference || chunk.task || chunk;
  return Object.assign({}, task, {
    id: task.id || chunk.taskId || chunk.todoistId || "",
    oid: task.oid || chunk.oid || "",
    content: task.content || chunk.content || chunk.title || "",
    description: task.description || chunk.description || "",
    projectId: task.projectId || chunk.projectId || "",
    projectName: task.projectName || chunk.projectName || "",
    sectionId: task.sectionId || chunk.sectionId || "",
    section: task.section || chunk.section || "",
    parentId: task.parentId || chunk.parentId || "",
    parentOid: task.parentOid || chunk.parentOid || "",
    parentTaskId: task.parentTaskId || chunk.parentTaskId || task.parentId || chunk.parentId || "",
    rootTaskId: task.rootTaskId || chunk.rootTaskId || "",
    rootOid: task.rootOid || chunk.rootOid || "",
    childTaskIds: task.childTaskIds || chunk.childTaskIds || [],
    childOids: task.childOids || chunk.childOids || [],
    treeDepth: task.treeDepth ?? chunk.treeDepth ?? null,
    treePath: task.treePath || chunk.treePath || [],
    siblingOrder: task.siblingOrder ?? chunk.siblingOrder ?? null,
    parentContent: task.parentContent || chunk.parentContent || "",
    isSubtask: task.isSubtask ?? Boolean(chunk.parentId || chunk.parentOid || chunk.sourceKind === "subtask-task-tree-record"),
    isCompleted: task.isCompleted ?? chunk.isCompleted,
    evidence_ids: task.evidence_ids || chunk.evidence_ids || chunk.evidenceIds || (chunk.evidenceId ? [chunk.evidenceId] : []),
    fact_refs: task.fact_refs || chunk.fact_refs || chunk.factRefs || [],
    structuredIdentity: task.structuredIdentity || chunk.structuredIdentity,
    relationship: task.relationship || chunk.relationship,
    currentState: task.currentState || chunk.currentState || (task.isCompleted || chunk.isCompleted ? "completed" : "open")
  });
}

function semanticTaskDedupeCandidateEnvelope(task = {}, candidate = {}, semanticScore = 0, reasons = []) {
  const existing = candidate.task || semanticTaskDedupeChunkIdentity(candidate.semanticChunk || candidate);
  const chunk = candidate.semanticChunk || candidate.chunk || {};
  const tree = taskTreeRepresentation(existing);
  return {
    taskId: String(candidate.taskId || candidate.id || existing.id || existing.todoistId || existing.oid || ""),
    sourceId: String(candidate.sourceId || chunk.sourceId || existing.sourceId || ""),
    id: candidate.id || candidate.taskId || existing.id || existing.todoistId || existing.oid || "",
    generatedTask: candidate.generatedTask || undefined,
    semanticScore: Number.isFinite(Number(semanticScore)) ? Number(semanticScore) : 0,
    evidence_ids: semanticDedupeList(candidate.evidence_ids || existing.evidence_ids || chunk.evidence_ids || chunk.evidenceIds || chunk.evidenceId),
    fact_refs: semanticDedupeList(candidate.fact_refs || existing.fact_refs || chunk.fact_refs || chunk.factRefs),
    structuredIdentity: tree.structuredIdentity,
    relationship: tree.relationship,
    currentState: tree.currentState,
    reasons: uniqueValues((reasons || []).map((reason) => singleLine(reason)).filter(Boolean)),
    task: existing,
    semanticChunk: chunk
  };
}

function semanticTaskDedupeStructuredConflict(source = {}, candidate = {}, options = {}) {
  const left = taskTreeRepresentation(source, options);
  const right = taskTreeRepresentation(candidate, options);
  const a = left.structuredIdentity || {};
  const b = right.structuredIdentity || {};
  const reasons = [];
  const hard = (label) => { reasons.push(label); return true; };
  if (left.currentState === "completed" || right.currentState === "completed") return { hardConflict: true, uncertain: false, reasons: ["completed task cannot satisfy generated work"] };
  if (a.projectId && b.projectId && a.projectId !== b.projectId) hard("different Todoist projects");
  if (a.projectName && b.projectName && a.projectName.toLowerCase() !== b.projectName.toLowerCase()) hard("different Todoist projects");
  if (a.sectionId && b.sectionId && a.sectionId !== b.sectionId && a.section && b.section) hard("different named sections");
  if (a.section && b.section && a.section.toLowerCase() !== b.section.toLowerCase() && a.section.toLowerCase() !== "inbox" && b.section.toLowerCase() !== "inbox") hard("different named sections");
  for (const [field, label] of [["action", "different actions"], ["owner", "different owners"], ["recipient", "different recipients"], ["reviewer", "different reviewers"], ["component", "different components"], ["deliverable", "different deliverables"]]) {
    if (a[field] && b[field] && a[field].toLowerCase() !== b[field].toLowerCase()) hard(label);
  }
  if (a.people?.length && b.people?.length && !a.people.some((person) => b.people.includes(person))) hard("different people");
  if (semanticTaskDedupeProgressConflict(a.progress, b.progress)) hard("different progress states");
  if (a.dueDate && b.dueDate && a.dueDate !== b.dueDate) hard("different due-date roles");
  if (a.deadlineDate && b.deadlineDate && a.deadlineDate !== b.deadlineDate) hard("different deadline roles");
  const parentA = left.relationship?.parentId || left.relationship?.parentOid || left.relationship?.parentContent;
  const parentB = right.relationship?.parentId || right.relationship?.parentOid || right.relationship?.parentContent;
  const hierarchyUncertain = Boolean(parentA && parentB && String(parentA) !== String(parentB));
  if (hierarchyUncertain) reasons.push("different parent context");
  const uncertain = hierarchyUncertain || !a.action && !a.deliverable && !a.component;
  return { hardConflict: reasons.some((reason) => reason.startsWith("different") || reason.startsWith("completed")), uncertain, reasons };
}

function buildSemanticTaskDedupeCandidates(task = {}, typedChunks = [], options = {}) {
  const source = taskTreeRepresentation(task, options);
  return (typedChunks || []).map((candidate) => {
    const existing = candidate.task || semanticTaskDedupeChunkIdentity(candidate);
    const score = Number(candidate.semanticScore ?? candidate.score ?? 0);
    const conflict = semanticTaskDedupeStructuredConflict(task, existing, options);
    return semanticTaskDedupeCandidateEnvelope(task, Object.assign({}, candidate, { task: existing }), score, conflict.reasons);
  }).filter((candidate) => candidate.taskId && candidate.currentState !== "completed").sort((left, right) => right.semanticScore - left.semanticScore || left.taskId.localeCompare(right.taskId));
}

function semanticTaskDedupeDecision(task = {}, candidates = [], options = {}) {
  const startedAt = Date.now();
  const top = (candidates || []).find((candidate) => candidate?.currentState !== "completed") || null;
  const baseTelemetry = Object.assign({ candidateCount: candidates?.length || 0, escalation: false, providerCalls: 0, providerCost: 0, elapsedMs: 0, degraded: false, degradedReason: "" }, options.telemetry || {});
  const clearThreshold = Number(options.clearThreshold ?? 0.88);
  const ambiguousThreshold = Number(options.ambiguousThreshold ?? 0.68);
  const candidateOutcomes = {};
  for (const candidate of candidates || []) {
    const candidateId = String(candidate.taskId || candidate.id || candidate.task?.id || "");
    if (!candidateId) continue;
    const conflict = semanticTaskDedupeStructuredConflict(task, candidate.task || {}, options);
    const score = Number(candidate.semanticScore || 0);
    const exactCandidate = Boolean((task.id && candidate.taskId && String(task.id) === String(candidate.taskId)) || (task.oid && candidate.task?.oid && String(task.oid).toUpperCase() === String(candidate.task.oid).toUpperCase()));
    candidateOutcomes[candidateId] = candidate.currentState === "completed" || conflict.hardConflict
      ? "create"
      : exactCandidate && !conflict.hardConflict ? "merge"
      : baseTelemetry.degraded ? "create"
      : score >= clearThreshold && !conflict.uncertain ? "merge" : score >= ambiguousThreshold ? "ambiguous-ai" : "create";
  }
  if (!top) return { outcome: "create", decision: "create", resolution: "local", candidateId: "", confidence: 0, semanticScore: 0, basis: ["no semantic task-reference candidate"], evidence_ids: [], fact_refs: [], candidate: null, candidateOutcomes, reasons: [], telemetry: Object.assign(baseTelemetry, { elapsedMs: Date.now() - startedAt }) };
  const conflict = semanticTaskDedupeStructuredConflict(task, top.task || {}, options);
  const exact = Boolean((task.id && top.taskId && String(task.id) === String(top.taskId)) || (task.oid && top.task?.oid && String(task.oid).toUpperCase() === String(top.task.oid).toUpperCase()));
  const score = Number(top.semanticScore || 0);
  let outcome = "create";
  let decision = "create";
  let basis = [];
  if (exact && !conflict.hardConflict) { outcome = "merge"; decision = "merge"; basis = ["exact task identity"]; }
  else if (conflict.hardConflict) basis = ["structured conflict gate", ...conflict.reasons];
  else if (!baseTelemetry.degraded && score >= clearThreshold && !conflict.uncertain) { outcome = "merge"; decision = "merge"; basis = ["local semantic index cosine", "structured identity agrees"]; }
  else if (!baseTelemetry.degraded && score >= ambiguousThreshold) { outcome = "ambiguous-ai"; decision = "ambiguous"; basis = ["bounded semantic candidate requires review", ...conflict.reasons]; baseTelemetry.escalation = true; }
  else basis = baseTelemetry.degraded ? ["semantic index unavailable", baseTelemetry.degradedReason || "degraded"] : ["semantic score below merge threshold"];
  if (conflict.hardConflict || score < ambiguousThreshold || (baseTelemetry.degraded && !exact)) {
    outcome = "create";
    decision = "create";
  }
  return {
    outcome, decision, resolution: outcome === "ambiguous-ai" ? "ai" : "local", candidateId: outcome === "create" ? "" : (top.taskId || ""), confidence: Math.round(Math.max(0, Math.min(1, score)) * 100), semanticScore: score,
    basis: uniqueValues(basis), evidence_ids: top.evidence_ids || [], fact_refs: top.fact_refs || [], candidate: top,
    reasons: uniqueValues([...(top.reasons || []), ...conflict.reasons]), candidateOutcomes, hardConflict: conflict.hardConflict, uncertain: conflict.uncertain,
    telemetry: Object.assign(baseTelemetry, { elapsedMs: Date.now() - startedAt })
  };
}

function bestTaskDeduplicationMatch(task, candidates = [], settings = DEFAULT_SETTINGS, options = {}) {
  if (options.semanticDedupeState?.enabled) {
    const state = options.semanticDedupeState;
    const fingerprintOptions = {
      provider: settings.aiModelProvider || "openai",
      model: settings.embeddingModel || DEFAULT_SETTINGS.embeddingModel,
      dimension: semanticEmbeddingRequestDimension(settings, "query", settings.semanticIndexMeta || {}),
      indexRevision: options.semanticIndexRevision || state.indexRevision || 0
    };
    const sourceFingerprint = taskTreeFingerprint(task, fingerprintOptions);
    const sourceEmbedding = state.generatedEmbeddingsByObject?.get(task) || state.generatedEmbeddings?.get(sourceFingerprint) || null;
    const scoredCandidates = (candidates || []).map((candidate) => {
      const candidateTask = candidate.generatedTask || candidate.task || semanticTaskDedupeChunkIdentity(candidate.semanticChunk || candidate);
      const candidateFingerprint = taskTreeFingerprint(candidateTask, fingerprintOptions);
      const candidateEmbedding = candidate.semanticChunk?.embedding || state.generatedEmbeddingsByObject?.get(candidateTask) || state.generatedEmbeddings?.get(candidateFingerprint) || null;
      const routedScores = state.routedScoresByFingerprint?.get(sourceFingerprint);
      const evidenceId = String(candidate.semanticChunk?.evidenceId || candidate.semanticChunk?.id || "");
      const routedScore = routedScores instanceof Map && evidenceId && routedScores.has(evidenceId)
        ? routedScores.get(evidenceId)
        : undefined;
      const semanticScore = routedScore !== undefined
        ? Number(routedScore || 0)
        : sourceEmbedding && candidateEmbedding ? cosine(sourceEmbedding, candidateEmbedding) : Number(candidate.semanticScore || 0);
      return Object.assign({}, candidate, { semanticScore });
    });
    const semanticCandidates = buildSemanticTaskDedupeCandidates(task, scoredCandidates, options);
    return Object.assign(semanticTaskDedupeDecision(task, semanticCandidates, Object.assign({}, options, { telemetry: options.semanticDedupeState.telemetry })), { sourceTask: task });
  }
  return {
    decision: "create",
    confidence: 0,
    reasons: ["semantic dedupe state unavailable; lexical fallback disabled"],
    candidate: null,
    degraded: true,
    degradedReason: "semantic-dedupe-state-unavailable",
    sourceTask: task
  };
}

const TASK_DEDUPE_SCOPE_IDENTIFIER_IGNORES = new Set(["ASAP", "FYI", "TODO"]);

function taskDedupeScopeIdentifiers(value = "") {
  return new Set((String(value || "").match(/\b[A-Z][A-Z0-9]{1,11}\b/g) || [])
    .filter((identifier) => !TASK_DEDUPE_SCOPE_IDENTIFIER_IGNORES.has(identifier) && !/^\d+$/.test(identifier)));
}

function conflictingIntraBatchTaskScopes(task = {}, existing = {}) {
  const source = taskDedupeScopeIdentifiers(task.content || "");
  const target = taskDedupeScopeIdentifiers(existing.content || "");
  if (!source.size || !target.size) return false;
  return tokenIntersection(source, target).length === 0;
}

function semanticTaskReferenceCandidateRanks(context = []) {
  const ranks = new Map();
  let rank = 0;
  for (const chunk of context || []) {
    if (chunk?.kind !== "todoist-task-reference" && chunk?.source !== "local-reference-table") continue;
    rank += 1;
    const text = String(chunk.text || chunk.content || chunk.chunk || "");
    for (const match of text.matchAll(/\boid:\s*([a-z0-9-]+)/gi)) {
      const oid = String(match[1] || "").toUpperCase();
      if (oid && !ranks.has(oid)) ranks.set(oid, rank);
    }
  }
  return ranks;
}

function applyTaskDeduplicationMatch(task, decision, settings = DEFAULT_SETTINGS, options = {}) {
  const existing = decision.task || decision.candidate?.task || {};
  task.id = decision.id || existing.id || task.id || "";
  task.oid = task.oid || generateUniqueOid(settings);
  task.labels = mergedTaskLabelsForDeduplication(task.labels || [], existing.labels || [], settings);
  task.priority = normalizePriority(task.priority || existing.priority || 1);
  task.due_date = task.due_date || existing.due_date || "";
  task.deadline_date = task.deadline_date || existing.deadline_date || "";
  task.duration = normalizeTodoistDuration(task.duration) || normalizeTodoistDuration(existing.duration);
  task.description = task.description || existing.description || "";
  task.section = task.section || existing.section || "";
  task.sectionId = task.sectionId || existing.sectionId || "";
  task.projectId = task.projectId || existing.projectId || "";
  task.projectName = task.projectName || existing.projectName || "";
  task.parentId = options.parentTask?.id || task.parentId || existing.parentId || "";
  task.parentOid = options.parentTask?.oid || task.parentOid || existing.parentOid || "";
  task.parentContent = options.parentTask?.content || task.parentContent || existing.parentContent || "";
  task.knowledge = taskKnowledgeSnapshot(task, settings, "", task.knowledge || existing.knowledge || null);
  task.descriptionShouldSync = true;
  task.deduplication = {
    todoistId: task.id,
    confidence: decision.confidence || 0,
    reasons: decision.reasons || []
  };
}

function taskDeduplicationMatchSummary(task, decision) {
  return {
    task: truncateAtWord(singleLine(task?.content || ""), 90),
    todoistId: decision.id || "",
    confidence: decision.confidence || 0,
    reasons: (decision.reasons || []).slice(0, 3)
  };
}

function taskDeduplicationCandidateFlag(task = {}, decision = {}, settings = DEFAULT_SETTINGS, options = {}) {
  const existing = decision.task || decision.candidate?.task || {};
  const isGenerated = Boolean(options.intraBatch || decision.candidate?.generatedTask);
  return {
    task: truncateAtWord(singleLine(task.content || ""), 120),
    candidate: truncateAtWord(singleLine(existing.content || ""), 120),
    candidateId: isGenerated ? "" : decision.id || existing.id || "",
    candidateType: isGenerated ? "same task generation batch" : "existing Todoist task",
    confidence: Math.round(decision.confidence || 0),
    reasons: (decision.reasons || []).slice(0, 3),
    projectName: singleLine(task.projectName || existing.projectName || ""),
    section: singleLine(task.section || existing.section || ""),
    parentContent: singleLine(options.parentContent || task.parentContent || existing.parentContent || ""),
    link: !isGenerated && (decision.id || existing.id) ? todoistTaskMarkdownLink(decision.id || existing.id, settings, existing.content || "Open task") : ""
  };
}

function flagPossibleDuplicateTask(stats = emptyTaskDeduplicationStats(), task = {}, decision = {}, settings = DEFAULT_SETTINGS, options = {}) {
  stats.candidateFlags.push(taskDeduplicationCandidateFlag(task, decision, settings, options));
  stats.ambiguous += 1;
  task.possibleDuplicate = {
    candidateId: decision.id || decision.candidate?.id || "",
    confidence: Number(decision.confidence || 0),
    reasons: (decision.reasons || []).slice(0, 3)
  };
  return task;
}

function taskDeduplicationCandidateChatMessage(flags = [], options = {}) {
  const source = options.source ? ` from ${options.source}` : "";
  const path = options.path ? `\nSource: ${options.path}` : "";
  const lines = [
    `${TASK_DUPLICATE_CANDIDATE_MARKER} Possible duplicate task${flags.length === 1 ? "" : "s"} found locally${source}.`,
    "No automatic merge was applied, and the marker is shown only in chat; it is never added to Todoist.",
    path,
    ""
  ].filter((line) => line !== "");
  flags.slice(0, 8).forEach((flag, index) => {
    const where = [flag.projectName ? `Project: ${flag.projectName}` : "", flag.section ? `Section: ${flag.section}` : "", flag.parentContent ? `Parent: ${truncateAtWord(flag.parentContent, 80)}` : ""].filter(Boolean).join(" | ");
    lines.push(`${index + 1}. ${TASK_DUPLICATE_CANDIDATE_MARKER} Generated task: ${flag.task || "Untitled task"}`);
    lines.push(`   Possible duplicate: ${flag.link || flag.candidate || "Earlier generated task"} (${flag.candidateType}, local score ${flag.confidence || 0})`);
    if (where) lines.push(`   Context: ${where}`);
    if (flag.reasons?.length) lines.push(`   Local evidence: ${flag.reasons.join("; ")}`);
  });
  if (flags.length > 8) lines.push(`...and ${flags.length - 8} more possible duplicate${flags.length - 8 === 1 ? "" : "s"}.`);
  lines.push("");
  lines.push("Review the generated task and likely match in Todoist.");
  return lines.join("\n");
}

function mergedTaskLabelsForDeduplication(generated = [], existing = [], settings = DEFAULT_SETTINGS) {
  const generatedLabels = (generated || []).map(cleanLabel).filter(Boolean);
  if (settings.taskDeduplicationMergeLabelsAdditive === false) return generatedLabels;
  return uniqueValues((existing || []).map(cleanLabel).filter(Boolean).concat(generatedLabels));
}

function isExplicitSubtaskRemovalInstruction(task = {}) {
  const text = `${task.content || ""} ${task.description || ""}`.toLowerCase();
  return /\b(no longer needed|not needed|obsolete|remove this subtask|remove subtask|delete this subtask|cancel this subtask)\b/.test(text);
}

function canonicalTaskMatchTitle(value = "") {
  return singleLine(scrubTaskDeduplicationBoilerplate(value))
    .replace(/%%\\[oid::\\s*[^\\]]+\\]%%/gi, " ")
    .replace(/#[\\w/-]+/g, " ")
    .replace(/[📅⏳✅⛔⏫🔼🔽]/g, " ")
    .replace(/\\b(?:due|deadline|priority|section|project)[:=]\\s*\\S+/gi, " ")
    .replace(/\\b\\d{4}-\\d{1,2}-\\d{1,2}\\b/g, " ")
    .replace(/[^a-z0-9]+/gi, " ")
    .replace(/\\s+/g, " ")
    .trim()
    .toLowerCase();
}

const TASK_DEDUPE_STOP_WORDS = new Set(["the", "and", "for", "with", "from", "this", "that", "task", "tasks", "todo", "action", "item", "items", "note", "notes", "meeting", "review", "follow", "about", "into", "onto", "have", "has", "was", "were", "will", "would", "should", "could", "need", "needs"]);

function taskDedupeTokenSet(text = "") {
  const tokens = String(text || "").toLowerCase().match(/[a-z0-9]{3,}/g) || [];
  return new Set(tokens.map(normalizeTaskDedupeToken).filter((token) => token && !TASK_DEDUPE_STOP_WORDS.has(token)));
}

function normalizeTaskDedupeToken(token = "") {
  const value = String(token || "").toLowerCase();
  if (value.length > 4 && value.endsWith("ies")) return `${value.slice(0, -3)}y`;
  if (value.length > 5 && /(ches|shes|xes|zes|ses)$/.test(value)) return value.slice(0, -2);
  if (value.length > 4 && value.endsWith("s") && !/(ss|us|is)$/.test(value)) return value.slice(0, -1);
  return value;
}

function tokenIntersection(left = new Set(), right = new Set()) {
  const matches = [];
  for (const token of left) if (right.has(token)) matches.push(token);
  return matches;
}

function taskDeduplicationContextText(task = {}) {
  const knowledge = task.knowledge || {};
  return scrubTaskDeduplicationBoilerplate([
    task.content,
    task.description,
    task.parentContent,
    task.parentDescription,
    task.childText,
    task.parentChildText,
    task.siblingText,
    taskDeduplicationSubtaskText(task),
    task.section,
    task.projectName,
    (task.labels || []).join(" "),
    knowledge.intent,
    knowledge.rationale,
    knowledge.problem,
    knowledge.outcome,
    knowledge.dependency,
    knowledge.nextStep,
    knowledge.evidence,
    (knowledge.people || []).join(" "),
    (knowledge.topics || []).join(" ")
  ].filter(Boolean).join(" "));
}

function taskDeduplicationSubtaskText(task = {}) {
  return (task.subtasks || [])
    .map((subtask) => [subtask?.content, subtask?.description].filter(Boolean).join(" "))
    .filter(Boolean)
    .join(" ");
}

function taskDeduplicationSourceContextText(options = {}) {
  const lines = ["Source and note context for duplicate detection and task generation:"];
  const includedPaths = new Set();
  if (options.source) lines.push(`Workflow: ${options.source}`);
  if (options.path) lines.push(`Source path: ${options.path}`);
  if (options.sectionName) lines.push(`Generated Todoist section: ${options.sectionName}`);
  const noteLines = (options.contextNotes || []).slice(0, 5).map((note) => {
    const title = note.title || note.path || "Context note";
    const path = note.path ? ` (${note.path})` : "";
    const excerpt = note.excerpt || note.summary || note.text || "";
    if (note.path) includedPaths.add(vaultRelativePath(note.path).toLowerCase());
    return `- ${singleLine(title)}${path}${excerpt ? `: ${truncateAtWord(scrubTaskDeduplicationBoilerplate(singleLine(excerpt)), 260)}` : ""}`;
  });
  if (noteLines.length) lines.push("Relevant notes:", ...noteLines);
  const semanticLines = (options.semanticContext || []).filter((chunk) => {
    const path = vaultRelativePath(chunk.path || chunk.file || "").toLowerCase();
    return !path || !includedPaths.has(path);
  }).slice(0, 5).map((chunk) => {
    const path = chunk.path || chunk.file || chunk.title || "Context";
    const text = chunk.text || chunk.content || chunk.chunk || "";
    return `- ${singleLine(path)}${text ? `: ${truncateAtWord(scrubTaskDeduplicationBoilerplate(singleLine(text)), 320)}` : ""}`;
  });
  if (semanticLines.length) lines.push("Relevant semantic context:", ...semanticLines);
  return lines.join("\n");
}

function taskDeduplicationAiTaskCard(task = {}) {
  const knowledge = task.knowledge || {};
  return [
    `Title: ${scrubTaskDeduplicationBoilerplate(task.content || "")}`,
    `Description: ${truncateAtWord(scrubTaskDeduplicationBoilerplate(task.description || ""), 900)}`,
    `Intent: ${scrubTaskDeduplicationBoilerplate(knowledge.intent || "")}`,
    `Rationale: ${scrubTaskDeduplicationBoilerplate(knowledge.rationale || "")}`,
    `People: ${(knowledge.people || []).join(", ")}`,
    `Topics: ${(knowledge.topics || []).join(", ")}`,
    `Parent: ${task.parentContent || ""}`,
    `Parent description: ${truncateAtWord(scrubTaskDeduplicationBoilerplate(task.parentDescription || ""), 500)}`,
    `Related parent/sibling/subtask context: ${truncateAtWord(scrubTaskDeduplicationBoilerplate([task.parentChildText, task.siblingText, task.childText, taskDeduplicationSubtaskText(task)].filter(Boolean).join(" ")), 700)}`,
    `Project: ${task.projectName || ""}`,
    `Section: ${task.section || ""}`,
    `Labels: ${(task.labels || []).join(", ")}`,
    `Due: ${task.due_date || ""}`,
    `Deadline: ${task.deadline_date || ""}`
  ].join("\n");
}

function scrubTaskDeduplicationBoilerplate(text = "") {
  return String(text || "")
    .replace(/\s*\[dup\?\]\s*/gi, " ")
    .replace(/\b\S*reply[-_\s]?to\S*\b/gi, " ")
    .replace(/\b(?:cc|copy|keep|include)\s+(?:the\s+)?(?:reply[-_\s]?to|tracking|ticket|mailbox|inbox)\s+(?:address|alias|mailbox|email)?\b/gi, " ")
    .replace(/\b(?:so|to ensure)\s+(?:records?|tickets?|emails?)\s+(?:are|is)\s+(?:captured|tracked|logged)\b/gi, " ")
    .replace(/\bunique\s+(?:email|mailbox|reply[-\s]?to|tracking)\s+(?:address|alias)\b/gi, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizeDate(value) {
  const parts = String(value).split("-").map((part) => part.padStart(2, "0"));
  if (parts[0].length === 2) parts[0] = `20${parts[0]}`;
  return `${parts[0]}-${parts[1]}-${parts[2]}`;
}

function makeSectionName(receivedAt, subject) {
  const date = new Date(receivedAt || Date.now());
  const yy = String(date.getFullYear()).slice(-2);
  const mm = String(date.getMonth() + 1).padStart(2, "0");
  const dd = String(date.getDate()).padStart(2, "0");
  const topic = String(subject || "No_Subject").replace(/^(re|fw|fwd):\s*/gi, "").replace(/[^a-z0-9]+/gi, "_").replace(/^_+|_+$/g, "").slice(0, 70) || "No_Subject";
  return `Email_${yy}_${mm}_${dd}_${topic}`;
}

function emailTaskNoteTitle(receivedAt, subject) {
  const date = new Date(receivedAt || Date.now());
  const datePart = Number.isFinite(date.getTime()) ? deviceDateString(date) : today();
  const topic = safeMarkdownFileName(String(subject || "No Subject").replace(/^(re|fw|fwd):\s*/gi, ""), 110) || "No Subject";
  return `${datePart} - ${topic}`;
}

function safeMarkdownFileName(value, maxLength = 120) {
  return singleLine(value)
    .replace(/[\\/#^[\]|:?*<>"]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, maxLength)
    .replace(/[. ]+$/g, "");
}

function uniqueMarkdownPath(app, folder, title) {
  const base = safeMarkdownFileName(title, 150) || "Untitled";
  let path = `${folder}/${base}.md`;
  let counter = 2;
  while (app.vault.getAbstractFileByPath(path)) {
    path = `${folder}/${base} ${counter}.md`;
    counter += 1;
  }
  return path;
}

function markdownTitleFromPath(path = "") {
  return String(path || "").split("/").pop()?.replace(/\.md$/i, "") || "";
}

function normalizeTaskSectionTitleMode(value) {
  return String(value || "").toLowerCase() === "ai" ? "ai" : "local";
}

function simpleFrontmatterScalar(value) {
  const raw = String(value || "").trim();
  if (!raw || /^[>|{}]/.test(raw)) return "";
  const quoted = raw.match(/^(["'])([\s\S]*)\1$/);
  if (quoted) return singleLine(quoted[2]).trim();
  const inlineArray = raw.match(/^\[\s*(?:(["'])([\s\S]*?)\1|([^\[\]{},]+))\s*\]$/);
  if (inlineArray) return singleLine(inlineArray[2] || inlineArray[3]).trim();
  if (/^\[|^\{|^&|^\*/.test(raw)) return "";
  return singleLine(raw.replace(/\s+#.*$/, "")).trim();
}

function noteFrontmatterSectionSubject(text = "") {
  const match = /^\s*---\s*\n([\s\S]*?)\n---(?:\n|$)/.exec(String(text || ""));
  if (!match) return "";
  const values = {};
  for (const line of match[1].split("\n")) {
    const field = /^\s*(project|purpose|topic|focus)\s*:\s*(.*?)\s*$/i.exec(line);
    if (!field) continue;
    const key = field[1].toLowerCase();
    const value = simpleFrontmatterScalar(field[2]);
    if (value && !values[key]) values[key] = value;
  }
  for (const key of ["project", "purpose", "topic", "focus"]) {
    if (values[key]) return values[key];
  }
  return "";
}

function noteTitleWithoutDate(title = "") {
  let value = singleLine(title).trim();
  if (!value) return "";
  const isoDate = /^\d{4}[-_]\d{1,2}[-_]\d{1,2}/;
  const monthDate = /^(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{1,2},?\s+\d{4}/i;
  if (isoDate.test(value)) value = value.replace(isoDate, "").replace(/^\s*[-–—:]\s*/, "").trim();
  else if (monthDate.test(value)) value = value.replace(monthDate, "").replace(/^\s*[-–—:]\s*/, "").trim();
  if (/^(?:\d{4}[-_]\d{1,2}[-_]\d{1,2}|(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{1,2},?\s+\d{4})$/i.test(value)) return "";
  return value;
}

function immediateContainingFolder(path = "") {
  const parts = String(path || "").split(/[\\/]/).filter(Boolean);
  return parts.length > 1 ? parts[parts.length - 2] : "";
}

function sectionSubjectFromFallback(sectionName = "") {
  const clean = cleanGeneratedSectionName(sectionName);
  const prefix = /^(?:Notes|Email)(?:_\d{2}_\d{2}_\d{2})?_/i.exec(clean);
  return prefix ? clean.slice(prefix[0].length) : "";
}

function sectionNameWithSubject(fallback, subject) {
  const cleanFallback = cleanGeneratedSectionName(fallback);
  const prefix = /^(Notes|Email)(?:(_\d{2}_\d{2}_\d{2}))?(?:_|$)/i.exec(cleanFallback);
  if (!prefix) return cleanFallback;
  const base = prefix[1] + (prefix[2] || "");
  const safeSubject = cleanGeneratedSectionName(subject || sectionSubjectFromFallback(cleanFallback)).slice(0, 70) || "Note";
  return cleanGeneratedSectionName(base + "_" + safeSubject);
}

function localNoteSectionSubject(sourceContext = {}, tasks = [], fallback = "") {
  const frontmatterSubject = noteFrontmatterSectionSubject(sourceContext.text || "");
  if (frontmatterSubject) return frontmatterSubject;
  const titleSubject = noteTitleWithoutDate(sourceContext.title || markdownTitleFromPath(sourceContext.path || ""));
  if (titleSubject) return titleSubject;
  const folderSubject = immediateContainingFolder(sourceContext.path || "");
  if (folderSubject) return folderSubject;
  const generatedTask = (tasks || []).find((task) => !task?.isSubtask && singleLine(task?.content || "").trim());
  if (generatedTask) return singleLine(generatedTask.content).trim();
  return sectionSubjectFromFallback(fallback) || "Note";
}

function localTaskSectionName(tasks = [], fallback = "", sourceType = "note", sourceContext = null) {
  const cleanFallback = cleanGeneratedSectionName(fallback);
  if (/^email$/i.test(String(sourceType || "")) || /^Email(?:_\d{2}_\d{2}_\d{2})?_/i.test(cleanFallback)) return cleanFallback;
  return sectionNameWithSubject(cleanFallback, localNoteSectionSubject(sourceContext || {}, tasks, cleanFallback));
}

function makeNoteSectionName(title, text = "", path = "") {
  const noteDate = extractNoteDate(title, text, path);
  const datePart = noteDate ? `_${noteDate.slice(2, 4)}_${noteDate.slice(5, 7)}_${noteDate.slice(8, 10)}` : "";
  const topicSource = String(title || "Note")
    .replace(/^\d{4}-\d{2}-\d{2}\s*[-–—:]\s*/i, "")
    .replace(/^[A-Z][a-z]+\s+\d{1,2},\s+\d{4}\s*[-–—:]\s*/i, "");
  const topic = topicSource.replace(/[^a-z0-9]+/gi, "_").replace(/^_+|_+$/g, "").slice(0, 70) || "Note";
  return `Notes${datePart}_${topic}`;
}

function cleanGeneratedSectionName(value) {
  const text = singleLine(value || "")
    .replace(/^section(?:\s+name|\s+title)?\s*:\s*/i, "")
    .replace(/^#+\s*/, "")
    .replace(/[\\/:*?"<>|]+/g, "_")
    .replace(/\s+/g, "_")
    .replace(/_+/g, "_")
    .replace(/^_+|_+$/g, "");
  return truncateAtWord(text || "Tasks", 120).replace(/\s+/g, "_");
}

function extractNoteDate(title, text, path) {
  const source = `${title || ""}\n${path || ""}\n${String(text || "").slice(0, 500)}`;
  const iso = /(?:created:\s*\[?"?|^|\D)(\d{4})-(\d{2})-(\d{2})/im.exec(source);
  if (iso) return `${iso[1]}-${iso[2]}-${iso[3]}`;
  const month = /(January|February|March|April|May|June|July|August|September|October|November|December)\s+(\d{1,2}),\s+(\d{4})/i.exec(source);
  if (month) {
    const index = ["january", "february", "march", "april", "may", "june", "july", "august", "september", "october", "november", "december"].indexOf(month[1].toLowerCase()) + 1;
    return `${month[3]}-${String(index).padStart(2, "0")}-${String(month[2]).padStart(2, "0")}`;
  }
  return "";
}

function extractOutputText(response) {
  const parts = [];
  for (const item of response.output || []) for (const content of item.content || []) if (content.type === "output_text" && content.text) parts.push(content.text);
  return parts.join("\n");
}

function extractGeminiText(response) {
  const parts = [];
  for (const candidate of response?.candidates || []) {
    for (const part of candidate.content?.parts || []) {
      if (part.text) parts.push(part.text);
    }
  }
  return parts.join("\n").trim();
}

function extractJsonPayload(text) {
  let value = String(text || "").trim()
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/```\s*$/i, "")
    .trim();
  try {
    JSON.parse(value);
    return value;
  } catch {}
  const start = value.search(/[\[{]/);
  if (start < 0) return value;
  const stack = [];
  let inString = false;
  let escaped = false;
  for (let i = start; i < value.length; i += 1) {
    const char = value[i];
    if (inString) {
      if (escaped) escaped = false;
      else if (char === "\\") escaped = true;
      else if (char === "\"") inString = false;
      continue;
    }
    if (char === "\"") {
      inString = true;
      continue;
    }
    if (char === "{" || char === "[") stack.push(char === "{" ? "}" : "]");
    else if (char === "}" || char === "]") {
      if (stack.pop() !== char) break;
      if (!stack.length) {
        const candidate = value.slice(start, i + 1);
        try {
          JSON.parse(candidate);
          return candidate;
        } catch {
          break;
        }
      }
    }
  }
  return value;
}

function elapsedMs(iso) {
  if (!iso) return Number.POSITIVE_INFINITY;
  const time = new Date(iso).getTime();
  if (!Number.isFinite(time)) return Number.POSITIVE_INFINITY;
  return Date.now() - time;
}

function delay(ms) {
  return new Promise((resolve) => window.setTimeout(resolve, ms));
}

function idlePause(timeoutMs = 50) {
  return new Promise((resolve, reject) => {
    let settled = false;
    let timerId = null;
    let idleId = null;
    let idleCancel = null;
    let channel = null;
    const cleanup = () => {
      if (timerId !== null) {
        try { window.clearTimeout(timerId); } catch {}
        timerId = null;
      }
      if (idleId !== null) {
        try { if (typeof idleCancel === "function") idleCancel(idleId); } catch {}
        idleId = null;
        idleCancel = null;
      }
      if (channel) {
        try { if (channel.port1) channel.port1.onmessage = null; } catch {}
        try { if (channel.port1 && typeof channel.port1.close === "function") channel.port1.close(); } catch {}
        try { if (channel.port2 && typeof channel.port2.close === "function") channel.port2.close(); } catch {}
        channel = null;
      }
    };
    const settle = () => {
      if (settled) return;
      settled = true;
      cleanup();
      resolve();
    };
    const fail = (error) => {
      if (settled) return;
      settled = true;
      cleanup();
      reject(error);
    };
    const readFailed = (message) => {
      const error = new Error(message || "semantic-index idle yield unavailable");
      error.code = "semantic-index-read-failed";
      return error;
    };
    let delayMs = Number(timeoutMs);
    if (!Number.isFinite(delayMs) || delayMs < 0) delayMs = 50;
    // Arm the bounded timer first so a timer that cannot be armed surfaces
    // as a diagnosable load-boundary failure instead of hanging on an idle
    // callback that never fires.
    try {
      timerId = window.setTimeout(settle, delayMs);
    } catch (error) {
      fail(readFailed(error?.message || "semantic-index idle timer unavailable"));
      return;
    }
    // Race an available MessageChannel task so throttled timers still settle
    // promptly. Both ports are closed on settlement. A channel that cannot
    // be constructed or posted to is treated as unavailable: it is discarded
    // while the armed timer and idle fallbacks stay alive. Only a timer that
    // cannot be armed rejects.
    const discardChannel = (ch) => {
      try { if (ch?.port1) ch.port1.onmessage = null; } catch {}
      try { if (ch?.port1 && typeof ch.port1.close === "function") ch.port1.close(); } catch {}
      try { if (ch?.port2 && typeof ch.port2.close === "function") ch.port2.close(); } catch {}
    };
    try {
      const ChannelCtor = (typeof window !== "undefined" && typeof window.MessageChannel === "function")
        ? window.MessageChannel
        : (typeof globalThis !== "undefined" && typeof globalThis.MessageChannel === "function" ? globalThis.MessageChannel : null);
      if (ChannelCtor) {
        let created = null;
        try {
          created = new ChannelCtor();
        } catch {
          created = null;
        }
        if (created) {
          channel = created;
          try {
            if (channel.port1) channel.port1.onmessage = settle;
            if (channel.port2) channel.port2.postMessage(null);
            else {
              discardChannel(channel);
              channel = null;
            }
          } catch {
            discardChannel(channel);
            channel = null;
          }
        }
      }
    } catch {
      discardChannel(channel);
      channel = null;
    }
    // Request idle time last so a synchronously-invoking callback still finds
    // the fallback timer armed and clears it; a never-firing callback falls
    // through to the timer/channel paths. If the callback already settled
    // synchronously, cancel its just-returned handle instead of storing it.
    try {
      if (typeof window !== "undefined" && typeof window.requestIdleCallback === "function") {
        const returnedId = window.requestIdleCallback(settle, { timeout: Math.max(50, delayMs) });
        const cancel = typeof window.cancelIdleCallback === "function" ? window.cancelIdleCallback.bind(window) : null;
        if (settled) {
          try { if (cancel) cancel(returnedId); } catch {}
        } else {
          idleId = returnedId;
          idleCancel = cancel;
        }
      } else if (typeof globalThis !== "undefined" && typeof globalThis.requestIdleCallback === "function") {
        const returnedId = globalThis.requestIdleCallback(settle, { timeout: Math.max(50, delayMs) });
        const cancel = typeof globalThis.cancelIdleCallback === "function" ? globalThis.cancelIdleCallback.bind(globalThis) : null;
        if (settled) {
          try { if (cancel) cancel(returnedId); } catch {}
        } else {
          idleId = returnedId;
          idleCancel = cancel;
        }
      }
    } catch {
      // Timer/channel paths remain; ignore idle registration failures.
    }
  });
}

